    /**
     * Liste globale des polices disponibles (envoyées par WebDev au chargement).
     * Ne doit pas être stockée dans documentState.
     *
     * @type {PoliceDisponible[]}
     */
    let policesDisponibles = [];

    /**
     * §3.10 - Liste des polices SYSTÈME (présentes sur l'atelier, hors dsn_police),
     * injectée par WebDev dans le wrapper de load (policesSysteme). Sert à classer
     * une police utilisée : gérée / système / inconnue (alerte d'ouverture).
     * @type {string[]}
     */
    let policesSysteme = [];

    /**
     * Active les logs détaillés de debug pour la conversion RTF ↔ Delta (Phase 7).
     * @type {boolean}
     */
    const DEBUG_PHASE7_RTF = false;

    /**
     * Active les logs de debug pour le fond (bgColor/transparent) des zones textQuill (Phase 7).
     * @type {boolean}
     */
    const DEBUG_PHASE7_BG = true;

    /**
     * Masque les logs des phases validées (0 à 6) afin de réduire le bruit en console.
     * (Les warnings/errors ne sont pas affectés.)
     * @type {boolean}
     */
    const FILTER_LEGACY_PHASE_LOGS_0_TO_6 = true;

    /**
     * Installe un filtre sur console.log pour masquer les logs des phases 0 à 6.
     * Conçu pour garder la console lisible pendant le debug Phase 7.
     *
     * @returns {void}
     */
    function installConsoleLogFilter() {
        if (!FILTER_LEGACY_PHASE_LOGS_0_TO_6) return;
        if (console.__marketeamPhaseFilterInstalled) return;

        const originalLog = console.log.bind(console);
        console.__marketeamPhaseFilterInstalled = true;

        console.log = (...args) => {
            try {
                const first = args && args.length > 0 ? args[0] : null;
                if (typeof first === 'string') {
                    // Formats ciblés : "🔧 PHASE X - ..." et "📋 PHASE X - ..."
                    const m = first.match(/(?:🔧|📋)\s*PHASE\s*(\d+)\b/i);
                    if (m) {
                        const phase = parseInt(m[1], 10);
                        if (!isNaN(phase) && phase >= 0 && phase <= 6) {
                            return; // ignorer
                        }
                    }
                }
            } catch (e) {}

            originalLog(...args);
        };
    }

    // Installer le filtre tôt (avant les logs d'init Phase 0-6).
    installConsoleLogFilter();
    
    /**
     * Stocke les instances Quill par ID de zone.
     * @type {Map<string, Quill>}
     */
    const quillInstances = new Map();

    /**
     * Stocke les ResizeObservers pour le copyfit réactif des zones textQuill.
     * Permet de recalculer automatiquement le copyfit quand le contenu change de taille
     * (ex: chargement de polices, modification du texte).
     * @type {Map<string, ResizeObserver>}
     */
    const copyfitResizeObservers = new Map();

    /**
     * Stocke les éléments DOM des areas par ID de zone.
     * Chaque zone avec une contrainte.geometrie.area a un élément area associé.
     * @type {Map<string, HTMLElement>}
     */
    const areaElements = new Map();

    /**
     * Flag pour éviter les boucles infinies lors du copyfit réactif.
     * Quand true, les ResizeObservers ignorent les changements de taille.
     * @type {boolean}
     */
    let isCopyfitRunning = false;
    
    // ════════════════════════════════════════════════════════════════════════
    // RÉSOLVEUR D'AFFICHAGE DES PASTILLES MERGE-TAG (V3.4)
    // Déclaré AVANT l'enregistrement Quill pour éviter tout risque de TDZ
    // (le MergeTagBlot référence mergeTagDisplayResolver dans son create()).
    // ════════════════════════════════════════════════════════════════════════
    // Le MergeTagBlot est créé AVANT que documentState soit défini (Section 12).
    // On utilise une fonction "trampoline" qui sera réassignée plus tard pour
    // résoudre la clé → libellé via documentState.champsFusion. Tant que le
    // résolveur n'est pas configuré, on retombe sur "@KEY@" brut (fallback de
    // sécurité §7.8.5 du cahier des charges).
    //
    // La clé technique peut contenir des espaces insécables (\u00A0) qui ont
    // été substitués aux espaces normaux à l'insertion (cf. insertTag) — on
    // les neutralise pour la recherche.
    let mergeTagDisplayResolver = (key) => {
        const cleanKey = String(key || '').replace(/\u00A0/g, ' ');
        return `@${cleanKey}@`;
    };

    /**
     * Configure (ou reconfigure) le résolveur d'affichage des pastilles.
     * À appeler après la déclaration de documentState et à chaque modification
     * significative de documentState.champsFusion (édition de libellé, ajout,
     * substitution post-mapping...).
     *
     * @param {(key: string) => string} resolver - Fonction key → texte affiché
     * @returns {void}
     */
    function setMergeTagDisplayResolver(resolver) {
        if (typeof resolver === 'function') {
            mergeTagDisplayResolver = resolver;
        }
    }

    /**
     * Axe 1 / Affichage uniforme — Retourne le libellé à afficher pour une
     * clé de champ de fusion (ex. "LOCAL_59ebaafb3457" → "Etiquette").
     *
     * Fine couche utilitaire au-dessus de `mergeTagDisplayResolver` pour
     * uniformiser le rendu visuel des zones code-barres, image et QR
     * intelligent. Le résolveur sous-jacent retombe sur "@KEY@" en cas
     * d'échec — ce comportement est conservé tel quel pour signaler à
     * l'utilisateur l'anomalie.
     *
     * IMPORTANT : aucune influence sur le stockage ; cette fonction sert
     * exclusivement à construire les badges / placeholders affichés à
     * l'écran (axes 2 et 3 inchangés).
     *
     * @param {string} key - Clé de champ (nom technique OU LOCAL_<localId>)
     * @returns {string} Libellé à afficher (ex: "Etiquette") ou "@KEY@" en fallback
     */
    function resolveChampLabel(key) {
        if (key === null || key === undefined || key === '') return '';
        try {
            return mergeTagDisplayResolver(String(key));
        } catch (e) {
            // Sécurité : si le résolveur n'est pas encore prêt, on rend la clé brute
            return `@${String(key)}@`;
        }
    }

    /**
     * Axe 1 / Affichage uniforme — Substitue dans une chaîne quelconque
     * tous les tokens `@KEY@` par le libellé résolu (via
     * `mergeTagDisplayResolver`). Utilisé pour les résumés QR
     * intelligents (`getQrDisplaySummary`) lorsque l'aperçu n'est pas
     * actif et qu'il reste des @KEY@ littéraux dans les champs.
     *
     * STRICTEMENT VISUEL : le contenu réel stocké dans
     * `qrConfig.fields[*]` n'est pas modifié (conserve les LOCAL_<id>).
     *
     * @param {string} text - Texte pouvant contenir des tokens @KEY@
     * @returns {string} Texte avec les tokens substitués par leurs libellés
     */
    function substituteMergeTagsForDisplay(text) {
        if (!text || typeof text !== 'string') return text;
        // Même regex que `replaceMergeFields` (lettres, chiffres, underscore).
        return text.replace(/@([A-Za-z0-9_]+)@/g, (match, key) => {
            const resolved = resolveChampLabel(key);
            // Si le résolveur retombe sur "@KEY@" (libellé introuvable),
            // on conserve le token tel quel (debug visible).
            if (resolved === `@${key}@`) return match;
            return resolved;
        });
    }

    /**
     * Module Clipboard personnalisé (PlainClipboard) pour filtrer le contenu collé.
     * Implémentation reproduite fidèlement depuis `POC QUILL/poc-quill.js`.
     *
     * Note : l'enregistrement est conditionné à la présence de Quill pour éviter
     * de casser l'application si le CDN n'est pas chargé.
     *
     * @extends Quill.import('modules/clipboard')
     */
    if (typeof Quill === 'function') {
        const Clipboard = Quill.import('modules/clipboard');
        const Delta = Quill.import('delta');
        
        class PlainClipboard extends Clipboard {
            /**
             * Intercepte le paste et filtre les formats non autorisés
             * @param {ClipboardEvent} e - Événement paste
             * @returns {void}
             */
            onPaste(e) {
                e.preventDefault();
                const range = this.quill.getSelection();
                if (!range) return;
                
                const clipboardData = e.clipboardData || window.clipboardData;
                const html = clipboardData.getData('text/html');
                const text = clipboardData.getData('text/plain');
                
                if (html) {
                    const filtered = this.filterHtml(html);
                    const delta = this.quill.clipboard.convert(filtered);
                    this.quill.updateContents(
                        new Delta().retain(range.index).delete(range.length).concat(delta),
                        'user'
                    );
                } else if (text) {
                    this.quill.insertText(range.index, text, 'user');
                }
                
                setTimeout(() => {
                    const newRange = this.quill.getSelection();
                    if (newRange) {
                        this.quill.setSelection(newRange.index, 0);
                    }
                }, 0);
            }
            
            /**
             * Filtre le HTML pour ne garder que les formats autorisés
             * @param {string} html - HTML brut
             * @returns {string} HTML filtré
             */
            filterHtml(html) {
                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = html;
                
                /**
                 * Nettoie récursivement un nœud HTML pour ne conserver que les tags simples.
                 * @param {Node} node - Nœud à nettoyer
                 * @returns {string} HTML nettoyé (ou texte)
                 */
                const cleanNode = (node) => {
                    if (node.nodeType === Node.TEXT_NODE) {
                        return node.textContent;
                    }
                    
                    if (node.nodeType !== Node.ELEMENT_NODE) {
                        return '';
                    }
                    
                    const tagName = node.tagName.toLowerCase();
                    let result = '';
                    
                    for (const child of node.childNodes) {
                        result += cleanNode(child);
                    }
                    
                    if (tagName === 'b' || tagName === 'strong') {
                        return `<strong>${result}</strong>`;
                    }
                    if (tagName === 'i' || tagName === 'em') {
                        return `<em>${result}</em>`;
                    }
                    if (tagName === 'u') {
                        return `<u>${result}</u>`;
                    }
                    if (tagName === 'br') {
                        return '<br>';
                    }
                    if (tagName === 'p' || tagName === 'div') {
                        return `<p>${result}</p>`;
                    }
                    
                    const style = node.getAttribute('style') || '';
                    const colorMatch = style.match(/color:\s*([^;]+)/i);
                    if (colorMatch && result) {
                        return `<span style="color: ${colorMatch[1]}">${result}</span>`;
                    }
                    
                    return result;
                };
                
                return cleanNode(tempDiv);
            }
        }
        
        Quill.register('modules/clipboard', PlainClipboard, true);

        // ════════════════════════════════════════════════════════════════════
        // MERGE TAG BLOT (V3.4 - Quill custom Embed)
        // Cf. docs/cahier_des_charges_creation_champs_fusion.md V2.2 §7.8
        //
        // Rend une pastille de champ de fusion qui AFFICHE le LIBELLÉ du champ
        // mais STOCKE la clé technique (@NOM@ ou @LOCAL_<localId>@). Le contenu
        // sous-jacent (RTF, JSON exporté) reste basé sur la clé technique — le
        // pipeline PSMD est inchangé.
        //
        // Implémentation : scénario B "déguisé" (cf. §7.8.3 du cahier) :
        // quill.getText() renvoie '\uFFFC' pour les embeds, donc on ne peut pas
        // se reposer naïvement dessus. Les fonctions de conversion locales
        // (quillDeltaToTextAndFormatage, deltaToRtf, createMergedDelta) sont
        // adaptées pour traiter explicitement les ops embed 'merge-tag' et
        // produire @KEY@ dans le contenu plat.
        //
        // Format de la valeur :
        //   value = { key: string }   où key = "PRENOM" ou "LOCAL_a1b2c3"
        // ════════════════════════════════════════════════════════════════════

        const Embed = Quill.import('blots/embed');

        class MergeTagBlot extends Embed {
            static create(value) {
                const node = super.create(value);
                const key = (typeof value === 'string') ? value : ((value && value.key) || '');
                // data-key est la SOURCE DE VÉRITÉ : on persiste la clé technique
                // (espaces déjà convertis en \u00A0 par le code appelant).
                node.setAttribute('data-key', key);
                node.setAttribute('contenteditable', 'false');
                node.classList.add('merge-tag-quill');
                // Rendu visuel : libellé résolu via le résolveur configuré
                // (renseigné après création de documentState — cf.
                // setMergeTagDisplayResolver). Fallback sécurité : @KEY@ brut.
                node.textContent = mergeTagDisplayResolver(key);
                return node;
            }

            static value(node) {
                return { key: node.getAttribute('data-key') || '' };
            }
        }

        MergeTagBlot.blotName = 'merge-tag';
        MergeTagBlot.tagName = 'span';
        MergeTagBlot.className = 'merge-tag-quill';

        Quill.register(MergeTagBlot, true);

        // Exposé pour debug console
        window.__MergeTagBlot = MergeTagBlot;
    }

    /**
     * Helper : détecte si une op Delta est un embed 'merge-tag'.
     * @param {{insert?: any}} op
     * @returns {boolean}
     */
    function isMergeTagOp(op) {
        return !!(op && op.insert && typeof op.insert === 'object' && op.insert['merge-tag']);
    }

    /**
     * Helper : extrait la clé technique (@KEY@) d'une op Delta merge-tag.
     * @param {{insert: {'merge-tag': {key: string}}}} op
     * @returns {string} Clé technique (ex: "PRENOM" ou "LOCAL_a1b2c3"), espaces
     *                  insécables convertis en espaces normaux.
     */
    function mergeTagOpKey(op) {
        const v = op && op.insert && op.insert['merge-tag'];
        if (!v) return '';
        const raw = (typeof v === 'string') ? v : (v.key || '');
        return String(raw).replace(/\u00A0/g, ' ');
    }

    /**
     * Helper : génère un identifiant local (UUID v4 simplifié) pour les champs
     * créés dans le Designer non encore mappés. Utilisé comme clé de
     * substitution dans le contenu (`@LOCAL_<localId>@`) et dans `donneesApercu`.
     * Conservé même après attribution de `nom` (traçabilité, cf. §4 du cahier).
     *
     * @returns {string} ID local (ex: "a1b2c3d4e5f6")
     */
    function generateLocalId() {
        // Privilégier crypto.randomUUID si disponible (navigateurs modernes),
        // sinon fallback Math.random — l'unicité côté Designer est suffisante.
        if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
            return crypto.randomUUID().replace(/-/g, '').substring(0, 12);
        }
        return Math.random().toString(36).substring(2, 8) + Date.now().toString(36).substring(-6);
    }

