    /**
     * Couleur thème du Designer (utilisée pour les placeholders et éléments UI).
     * @type {string}
     */
    const THEME_COLOR = '#7c3aed'; // Violet Marketeam

    /**
     * Proportion par défaut de l'icône placeholder image (0.5 = 50% de la zone).
     * @type {number}
     */
    const IMAGE_PLACEHOLDER_SCALE = 0.5;

    /**
     * Marge intérieure du cadre placeholder image en pixels.
     * @type {number}
     */
    const IMAGE_PLACEHOLDER_INSET = 10;

    /**
     * Rayon des coins arrondis du cadre placeholder image en pixels.
     * @type {number}
     */
    const IMAGE_PLACEHOLDER_BORDER_RADIUS = 8;

    /**
     * Épaisseur de la bordure du cadre placeholder image en pixels.
     * @type {number}
     */
    const IMAGE_PLACEHOLDER_BORDER_WIDTH = 3;

    /**
     * État du dernier champ QR Code intelligent focalisé.
     * Utilisé pour l'insertion par double-clic depuis toolbar-data.
     * @type {{inputElement: HTMLInputElement|HTMLTextAreaElement|null, selectionStart: number, selectionEnd: number}}
     */
    let lastFocusedQrInput = {
        inputElement: null,
        selectionStart: 0,
        selectionEnd: 0
    };

    /**
     * Applique un thème coloré au Designer.
     * Met à jour l'attribut data-theme sur l'élément racine du document.
     * 
     * @param {string} themeName - Code du thème ('MKT', 'TTB', 'LTR')
     * @returns {void}
     * 
     * @example
     * applyTheme('MKT');  // Applique le thème bleu Marketeam
     * applyTheme('TTB');  // Applique le thème violet Tract
     * applyTheme('LTR');  // Applique le thème jaune Courrier
     */
    function applyTheme(themeName) {
        // Valider le thème (fallback sur défaut si invalide)
        const validTheme = THEMES[themeName] ? themeName : DEFAULT_THEME;
        
        // Appliquer l'attribut data-theme sur le document
        document.documentElement.setAttribute('data-theme', validTheme);
        
    }

    // Exposer la fonction applyTheme globalement pour les tests
    window.applyTheme = applyTheme;

