    /**
     * Applique les contraintes de style sur une toolbar en mode Standard.
     * Masque les sections dont la contrainte *Modifiable = false.
     * 
     * En mode Template, cette fonction ne fait rien (le créateur peut tout modifier).
     * 
     * @param {HTMLElement} toolbar - Élément toolbar à modifier
     * @param {string} zoneType - Type de zone ('textQuill', 'image', 'barcode', 'qr')
     * @param {ZoneContrainte} contrainte - Contraintes de la zone
     * @returns {void}
     * 
     * @example
     * const contrainte = zoneData.contrainte;
     * applyConstraintsToToolbar(quillToolbar, 'textQuill', contrainte);
     */
    function applyConstraintsToToolbar(toolbar, zoneType, contrainte) {
        if (!toolbar || !contrainte) return;
        
        // En mode Template, ne pas appliquer les contraintes
        if (isTemplateMode()) {
            resetToolbarSectionsVisibility(toolbar);
            return;
        }
        
        // Réinitialiser d'abord
        resetToolbarSectionsVisibility(toolbar);
        
        const { geometrie, style, global } = contrainte;
        
        // --- Contraintes globales ---
        
        // pageModifiable = false → masquer section "page"
        if (global?.pageModifiable === false) {
            setSectionVisibility(toolbar, 'page', false);
        }
        
        // --- Contraintes géométriques ---
        
        // locked OU positionFixe → masquer section "geometry"
        if (geometrie?.locked || geometrie?.positionFixe) {
            setSectionVisibility(toolbar, 'geometry', false);
        }
        
        // locked → checkbox "Verrouiller" cochée et grisée
        if (geometrie?.locked) {
            // Déterminer le wrapper selon le type de zone
            const lockWrapperIds = {
                'textQuill': 'quill-chk-locked-wrapper',
                'text': 'quill-chk-locked-wrapper',
                'image': 'image-chk-locked-wrapper',
                'barcode': 'barcode-chk-locked-wrapper',
                'qr': 'qrcode-chk-locked-wrapper'
            };
            const wrapperId = lockWrapperIds[zoneType];
            if (wrapperId) {
                setCheckboxDisabled(toolbar, wrapperId, true, true);
            }
        }
        
        // --- Contraintes de style selon le type de zone ---
        
        if (!style) return;
        
        switch (zoneType) {
            case 'text':
            case 'textQuill':
                // contenuModifiable → Quill readonly
                if (style.contenuModifiable === false) {
                    setQuillReadonly(true);
                } else {
                    setQuillReadonly(false);
                }
                // typographieModifiable
                if (style.typographieModifiable === false) {
                    setSectionVisibility(toolbar, 'typography', false);
                }
                // alignementsModifiable
                if (style.alignementsModifiable === false) {
                    setSectionVisibility(toolbar, 'paragraph', false);
                }
                // fondModifiable
                if (style.fondModifiable === false) {
                    setSectionVisibility(toolbar, 'background', false);
                }
                // bordureModifiable
                if (style.bordureModifiable === false) {
                    setSectionVisibility(toolbar, 'border', false);
                }
                break;
                
            case 'image':
                // typeSourceModifiable → masquer boutons radio Fixe/Champ
                if (style.typeSourceModifiable === false) {
                    hideImageSourceRadios(toolbar);
                }
                // imageModifiable → masquer upload et sélection champ
                if (style.imageModifiable === false) {
                    hideImageControls(toolbar);
                }
                // Si les deux sont false, masquer toute la section source
                if (style.typeSourceModifiable === false && style.imageModifiable === false) {
                    setSectionVisibility(toolbar, 'source', false);
                }
                // affichageModifiable
                if (style.affichageModifiable === false) {
                    setSectionVisibility(toolbar, 'display', false);
                }
                // fondModifiable
                if (style.fondModifiable === false) {
                    setSectionVisibility(toolbar, 'background', false);
                }
                // bordureModifiable
                if (style.bordureModifiable === false) {
                    setSectionVisibility(toolbar, 'border', false);
                }
                break;
                
            case 'barcode':
                // typeCodeModifiable
                if (style.typeCodeModifiable === false) {
                    setSectionVisibility(toolbar, 'barcode-type', false);
                }
                // typeSourceModifiable → masquer boutons radio Fixe/Champ
                if (style.typeSourceModifiable === false) {
                    hideBarcodeSourceRadios(toolbar);
                }
                // donneesModifiable → masquer champs valeur/sélection + section qr-smart
                if (style.donneesModifiable === false) {
                    hideBarcodeDataControls(toolbar);
                    setSectionVisibility(toolbar, 'qr-smart', false);
                }
                // Si typeSourceModifiable ET donneesModifiable sont false, masquer section data
                if (style.typeSourceModifiable === false && style.donneesModifiable === false) {
                    setSectionVisibility(toolbar, 'data', false);
                }
                // apparenceModifiable
                if (style.apparenceModifiable === false) {
                    setSectionVisibility(toolbar, 'display', false);
                }
                // fondModifiable
                if (style.fondModifiable === false) {
                    setSectionVisibility(toolbar, 'background', false);
                }
                break;
                
            case 'qr':
                // couleursModifiable
                if (style.couleursModifiable === false) {
                    setSectionVisibility(toolbar, 'background', false);
                }
                break;
        }
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // BADGES ZONES
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * Met à jour le badge système d'une zone.
     * Affiche le libellé système si la zone est marquée comme système
     * avec un libellé non vide.
     * 
     * Les zones système sont des zones spéciales (ex: numéro de page, date)
     * qui ne peuvent pas être supprimées ou multi-sélectionnées.
     * 
     * @param {string} zoneId - Identifiant de la zone (ex: "zone-1")
     * @returns {void}
     * 
     * @example
     * // Zone système avec libellé
     * setZoneSysteme(zoneData, true);
     * setZoneSystemeLibelle(zoneData, 'N° Page');
     * updateSystemeBadge('zone-1'); // → Affiche badge "N° Page"
     * 
     * // Zone non système
     * setZoneSysteme(zoneData, false);
     * updateSystemeBadge('zone-1'); // → Supprime le badge
     */
    function updateSystemeBadge(zoneId) {
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        if (!zoneData) return;
        
        const zoneEl = document.getElementById(zoneId);
        if (!zoneEl) return;
        
        // Chercher un badge existant
        let badge = zoneEl.querySelector('.systeme-badge');
        
        // Vérifier si on doit afficher le badge
        const libelle = getZoneSystemeLibelle(zoneData);
        const shouldShow = isZoneSysteme(zoneData) && libelle;
        
        if (!shouldShow) {
            // Supprimer le badge s'il existe
            if (badge) badge.remove();
            return;
        }
        
        // Créer le badge s'il n'existe pas
        if (!badge) {
            badge = document.createElement('span');
            badge.className = 'systeme-badge';
            zoneEl.appendChild(badge);
        }
        
        // Mettre à jour le contenu
        badge.textContent = libelle;
    }

    /**
     * Met à jour le badge "Zone contrainte" pour une zone donnée.
     * Le badge est affiché uniquement si la zone a une propriété `contrainte` définie.
     * 
     * @param {string} zoneId - Identifiant de la zone (ex: "zone-1")
     * @returns {void}
     * 
     * @example
     * // Zone avec contrainte
     * zoneData.contrainte = { positionFixe: true, nonSupprimable: true };
     * updateContrainteBadge('zone-1'); // → Affiche badge "Zone contrainte"
     * 
     * // Zone sans contrainte
     * updateContrainteBadge('zone-2'); // → Supprime le badge
     */
    function updateContrainteBadge(zoneId) {
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        if (!zoneData) return;
        
        const zoneEl = document.getElementById(zoneId);
        if (!zoneEl) return;
        
        // Chercher un badge existant
        let badge = zoneEl.querySelector('.contrainte-badge');
        
        // Vérifier si on doit afficher le badge
        const shouldShow = zoneData.contrainte && 
            (zoneData.contrainte?.geometrie?.positionFixe || zoneData.contrainte?.global?.nonSupprimable);
        
        if (!shouldShow) {
            // Supprimer le badge s'il existe
            if (badge) badge.remove();
            return;
        }
        
        // Créer le badge s'il n'existe pas
        if (!badge) {
            badge = document.createElement('span');
            badge.className = 'contrainte-badge';
            zoneEl.appendChild(badge);
        }
        
        // Mettre à jour le contenu
        badge.textContent = 'Zone contrainte';
    }

    /**
     * Crée l'élément DOM de l'area pour une zone contrainte.
     * L'area est un rectangle avec bordure pointillée qui délimite
     * la zone autorisée pour le déplacement et le redimensionnement.
     * En mode Template, l'area possède 8 poignées de redimensionnement.
     * 
     * @param {string} zoneId - ID de la zone associée
     * @param {AreaContrainte} area - Définition de l'area (xMm, yMm, wMm, hMm)
     * @returns {HTMLElement} L'élément DOM créé
     */
    function createAreaElement(zoneId, area) {
        // Supprimer l'area existante si présente
        removeAreaElement(zoneId);
        
        // Créer l'élément (masqué par défaut, visible uniquement quand la zone est sélectionnée)
        const areaEl = document.createElement('div');
        areaEl.classList.add('zone-area');
        areaEl.dataset.zoneId = zoneId;
        
        // Positionner en page DOM px (format fini mm + offset fond perdu)
        const fpAreaEl = getFondPerduOffset();
        areaEl.style.left = (mmToPx(area.xMm) + fpAreaEl.gauchePx) + 'px';
        areaEl.style.top = (mmToPx(area.yMm) + fpAreaEl.hautPx) + 'px';
        areaEl.style.width = mmToPx(area.wMm) + 'px';
        areaEl.style.height = mmToPx(area.hMm) + 'px';
        
        // Ajouter les 8 poignées de redimensionnement (mode Template uniquement)
        const handles = ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'];
        handles.forEach(pos => {
            const handle = document.createElement('div');
            handle.className = `area-handle area-handle-${pos}`;
            handle.dataset.handle = pos;
            areaEl.appendChild(handle);
        });
        
        // Ajouter au DOM (avant les zones pour être derrière)
        a4Page.insertBefore(areaEl, a4Page.firstChild);
        
        // Stocker la référence
        areaElements.set(zoneId, areaEl);
        
        
        return areaEl;
    }
    
    /**
     * Supprime l'élément DOM de l'area d'une zone.
     * 
     * @param {string} zoneId - ID de la zone associée
     * @returns {void}
     * 
     * @example
     * removeAreaElement('zone-1');
     */
    function removeAreaElement(zoneId) {
        const areaEl = areaElements.get(zoneId);
        if (areaEl) {
            areaEl.remove();
            areaElements.delete(zoneId);
        }
    }

    /**
     * Supprime toutes les areas du DOM et vide la Map.
     * Utilisé lors du reset ou de la restauration d'état.
     * 
     * @returns {void}
     * 
     * @example
     * clearAllAreas(); // Supprime toutes les areas
     */
    function clearAllAreas() {
        areaElements.forEach((areaEl, zoneId) => {
            areaEl.remove();
        });
        areaElements.clear();
    }

    // ═══════════════════════════════════════════════════════════════════════════════
    // AREA INTERACTIVE - DRAG ET RESIZE (MODE TEMPLATE)
    // ═══════════════════════════════════════════════════════════════════════════════
    
    /** @type {boolean} Flag indiquant si une area est en cours de drag */
    let isAreaDragging = false;
    
    /** @type {boolean} Flag indiquant si une area est en cours de resize */
    let isAreaResizing = false;
    
    /** @type {HTMLElement|null} L'area actuellement manipulée */
    let activeArea = null;
    
    /** @type {string|null} La poignée de resize active (nw, n, ne, e, se, s, sw, w) */
    let activeAreaHandle = null;
    
    /** @type {{x: number, y: number, areaX: number, areaY: number, areaW: number, areaH: number}} Position de départ */
    let areaStartPos = { x: 0, y: 0, areaX: 0, areaY: 0, areaW: 0, areaH: 0 };
    
    /**
     * Calcule les limites de l'area en fonction du document et de la zone.
     * L'area ne peut pas sortir des marges du document et doit toujours englober la zone.
     * @param {string} zoneId - ID de la zone associée
     * @returns {Object} Limites pour le document et contraintes pour englober la zone
     */
    function getAreaLimits(zoneId) {
        const limits = getGeometryLimits();
        const fp = getFondPerduOffset();
        const zoneEl = document.getElementById(zoneId);
        
        // Position et dimensions de la zone (l'area doit toujours l'englober)
        const zoneLeft = zoneEl ? zoneEl.offsetLeft : 0;
        const zoneTop = zoneEl ? zoneEl.offsetTop : 0;
        const zoneWidth = zoneEl ? zoneEl.offsetWidth : 20;
        const zoneHeight = zoneEl ? zoneEl.offsetHeight : 20;
        const zoneRight = zoneLeft + zoneWidth;
        const zoneBottom = zoneTop + zoneHeight;
        
        return {
            // Limites du document (format fini + marge, en pixels page DOM)
            docMinXPx: mmToPx(limits.marginMm) + fp.gauchePx,
            docMinYPx: mmToPx(limits.marginMm) + fp.hautPx,
            docMaxXPx: mmToPx(limits.maxX) + fp.gauchePx,
            docMaxYPx: mmToPx(limits.maxY) + fp.hautPx,
            pageWidthPx: mmToPx(limits.pageWidthMm),
            pageHeightPx: mmToPx(limits.pageHeightMm),
            // Contraintes pour englober la zone
            zoneLeft: zoneLeft,
            zoneTop: zoneTop,
            zoneRight: zoneRight,
            zoneBottom: zoneBottom,
            zoneWidth: zoneWidth,
            zoneHeight: zoneHeight
        };
    }
    
    /**
     * Démarre le drag ou resize d'une area.
     * @param {MouseEvent} e - Événement mousedown
     */
    function startAreaInteraction(e) {
        // Ne fonctionner qu'en mode Template
        if (!isTemplateMode()) return;
        
        const areaEl = e.target.closest('.zone-area');
        if (!areaEl) return;
        
        const handle = e.target.closest('.area-handle');
        const zoneId = areaEl.dataset.zoneId;
        
        // Stocker les positions de départ (area ET zone)
        const zoneEl = document.getElementById(zoneId);
        areaStartPos = {
            x: e.clientX,
            y: e.clientY,
            areaX: areaEl.offsetLeft,
            areaY: areaEl.offsetTop,
            areaW: areaEl.offsetWidth,
            areaH: areaEl.offsetHeight,
            // Position initiale de la zone (pour la déplacer avec l'area)
            zoneX: zoneEl ? zoneEl.offsetLeft : 0,
            zoneY: zoneEl ? zoneEl.offsetTop : 0
        };
        
        activeArea = areaEl;
        
        if (handle) {
            // Resize
            isAreaResizing = true;
            activeAreaHandle = handle.dataset.handle;
            areaEl.classList.add('area-resizing');
        } else {
            // Drag
            isAreaDragging = true;
            areaEl.classList.add('area-dragging');
        }
        
        e.preventDefault();
        e.stopPropagation();
    }
    
    /**
     * Gère le déplacement pendant le drag ou resize d'une area.
     * @param {MouseEvent} e - Événement mousemove
     */
    function handleAreaMove(e) {
        if (!activeArea) return;
        if (!isAreaDragging && !isAreaResizing) return;
        
        const zoneId = activeArea.dataset.zoneId;
        const limits = getAreaLimits(zoneId);
        
        // Diviser par zoomLevel pour compenser le scale CSS de la page
        const deltaX = (e.clientX - areaStartPos.x) / zoomLevel;
        const deltaY = (e.clientY - areaStartPos.y) / zoomLevel;
        
        let newX = areaStartPos.areaX;
        let newY = areaStartPos.areaY;
        let newW = areaStartPos.areaW;
        let newH = areaStartPos.areaH;
        
        if (isAreaDragging) {
            // Déplacement simple de l'area
            newX = areaStartPos.areaX + deltaX;
            newY = areaStartPos.areaY + deltaY;
            
            // Contraindre l'area aux limites du document
            newX = Math.max(limits.docMinXPx, Math.min(newX, limits.docMaxXPx - newW));
            newY = Math.max(limits.docMinYPx, Math.min(newY, limits.docMaxYPx - newH));
            
            // Calculer la nouvelle position de la zone (suit l'area)
            const zoneEl = document.getElementById(zoneId);
            if (zoneEl) {
                // Calculer le déplacement RÉEL de l'area (après contraintes aux limites)
                const realDeltaX = newX - areaStartPos.areaX;
                const realDeltaY = newY - areaStartPos.areaY;
                
                // La zone suit le déplacement RÉEL de l'area, pas le delta brut
                // Ainsi quand l'area est bloquée, la zone ne bouge plus
                let newZoneX = areaStartPos.zoneX + realDeltaX;
                let newZoneY = areaStartPos.zoneY + realDeltaY;
                
                // Contraindre la zone pour rester dans l'area
                // Bord gauche de la zone >= bord gauche de l'area
                newZoneX = Math.max(newX, newZoneX);
                // Bord haut de la zone >= bord haut de l'area
                newZoneY = Math.max(newY, newZoneY);
                // Bord droit de la zone <= bord droit de l'area
                if (newZoneX + zoneEl.offsetWidth > newX + newW) {
                    newZoneX = newX + newW - zoneEl.offsetWidth;
                }
                // Bord bas de la zone <= bord bas de l'area
                if (newZoneY + zoneEl.offsetHeight > newY + newH) {
                    newZoneY = newY + newH - zoneEl.offsetHeight;
                }
                
                // Appliquer la nouvelle position à la zone
                zoneEl.style.left = newZoneX + 'px';
                zoneEl.style.top = newZoneY + 'px';
            }
            
        } else if (isAreaResizing) {
            // Resize selon la poignée
            switch (activeAreaHandle) {
                case 'nw': // Nord-Ouest : change X, Y, W, H
                    newX = areaStartPos.areaX + deltaX;
                    newY = areaStartPos.areaY + deltaY;
                    newW = areaStartPos.areaW - deltaX;
                    newH = areaStartPos.areaH - deltaY;
                    break;
                case 'n': // Nord : change Y, H
                    newY = areaStartPos.areaY + deltaY;
                    newH = areaStartPos.areaH - deltaY;
                    break;
                case 'ne': // Nord-Est : change Y, W, H
                    newY = areaStartPos.areaY + deltaY;
                    newW = areaStartPos.areaW + deltaX;
                    newH = areaStartPos.areaH - deltaY;
                    break;
                case 'e': // Est : change W
                    newW = areaStartPos.areaW + deltaX;
                    break;
                case 'se': // Sud-Est : change W, H
                    newW = areaStartPos.areaW + deltaX;
                    newH = areaStartPos.areaH + deltaY;
                    break;
                case 's': // Sud : change H
                    newH = areaStartPos.areaH + deltaY;
                    break;
                case 'sw': // Sud-Ouest : change X, W, H
                    newX = areaStartPos.areaX + deltaX;
                    newW = areaStartPos.areaW - deltaX;
                    newH = areaStartPos.areaH + deltaY;
                    break;
                case 'w': // Ouest : change X, W
                    newX = areaStartPos.areaX + deltaX;
                    newW = areaStartPos.areaW - deltaX;
                    break;
            }
            
            // ═══════════════════════════════════════════════════════════════
            // CONTRAINTE PRINCIPALE : L'area doit toujours englober la zone
            // ═══════════════════════════════════════════════════════════════
            
            // Bord gauche : ne peut pas être à droite du bord gauche de la zone
            if (newX > limits.zoneLeft) {
                const diff = newX - limits.zoneLeft;
                newX = limits.zoneLeft;
                // Si on redimensionne par la gauche, ajuster la largeur
                if (activeAreaHandle.includes('w')) {
                    newW = areaStartPos.areaW - (limits.zoneLeft - areaStartPos.areaX);
                }
            }
            
            // Bord haut : ne peut pas être en dessous du bord haut de la zone
            if (newY > limits.zoneTop) {
                const diff = newY - limits.zoneTop;
                newY = limits.zoneTop;
                // Si on redimensionne par le haut, ajuster la hauteur
                if (activeAreaHandle.includes('n')) {
                    newH = areaStartPos.areaH - (limits.zoneTop - areaStartPos.areaY);
                }
            }
            
            // Bord droit : ne peut pas être à gauche du bord droit de la zone
            if (newX + newW < limits.zoneRight) {
                newW = limits.zoneRight - newX;
            }
            
            // Bord bas : ne peut pas être au-dessus du bord bas de la zone
            if (newY + newH < limits.zoneBottom) {
                newH = limits.zoneBottom - newY;
            }
            
            // ═══════════════════════════════════════════════════════════════
            // Contraindre aux limites du document (marges)
            // ═══════════════════════════════════════════════════════════════
            newX = Math.max(limits.docMinXPx, newX);
            newY = Math.max(limits.docMinYPx, newY);
            if (newX + newW > limits.docMaxXPx) newW = limits.docMaxXPx - newX;
            if (newY + newH > limits.docMaxYPx) newH = limits.docMaxYPx - newY;
        }
        
        // Appliquer les nouvelles dimensions
        activeArea.style.left = newX + 'px';
        activeArea.style.top = newY + 'px';
        activeArea.style.width = newW + 'px';
        activeArea.style.height = newH + 'px';
        
        // Mettre à jour les champs de la toolbar en temps réel
        updateAreaFieldsFromPixels(zoneId, newX, newY, newW, newH);
    }
    
    /**
     * Termine le drag ou resize d'une area.
     * @param {MouseEvent} e - Événement mouseup
     */
    function endAreaInteraction(e) {
        if (!activeArea) return;
        if (!isAreaDragging && !isAreaResizing) return;
        
        const zoneId = activeArea.dataset.zoneId;
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        
        // Récupérer les dimensions finales (page DOM px)
        const finalX = activeArea.offsetLeft;
        const finalY = activeArea.offsetTop;
        const finalW = activeArea.offsetWidth;
        const finalH = activeArea.offsetHeight;
        const fpArea = getFondPerduOffset();
        
        // Mettre à jour les données de contrainte (area en format fini mm)
        if (zoneData && zoneData.contrainte && zoneData.contrainte.geometrie) {
            zoneData.contrainte.geometrie.area = {
                xMm: pxToMm(finalX - fpArea.gauchePx),
                yMm: pxToMm(finalY - fpArea.hautPx),
                wMm: pxToMm(finalW),
                hMm: pxToMm(finalH)
            };
            
        }
        
        // Si c'était un drag, mettre à jour aussi la position de la zone
        if (isAreaDragging) {
            const zoneEl = document.getElementById(zoneId);
            if (zoneEl && zoneData) {
                zoneData.x = zoneEl.offsetLeft;
                zoneData.y = zoneEl.offsetTop;
                zoneData.xMm = pxToMm(zoneEl.offsetLeft - fpArea.gauchePx);
                zoneData.yMm = pxToMm(zoneEl.offsetTop - fpArea.hautPx);
            }
        }
        
        // Sauvegarder
        saveToLocalStorage();
        saveState('Modification de la zone autorisée');
        
        // Valider et corriger les contraintes de taille après modification de l'area
        validateAndCorrectSizeConstraints(zoneId);
        
        // Reset
        activeArea.classList.remove('area-dragging', 'area-resizing');
        activeArea = null;
        activeAreaHandle = null;
        isAreaDragging = false;
        isAreaResizing = false;
    }
    
    /**
     * Met à jour les champs X, Y, L, H de la toolbar avec les valeurs en pixels converties en mm.
     * @param {string} zoneId - ID de la zone
     * @param {number} xPx - Position X en pixels
     * @param {number} yPx - Position Y en pixels
     * @param {number} wPx - Largeur en pixels
     * @param {number} hPx - Hauteur en pixels
     */
    function updateAreaFieldsFromPixels(zoneId, xPx, yPx, wPx, hPx) {
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        if (!zoneData) return;
        
        const toolbar = getActiveToolbarForType(zoneData.type);
        if (!toolbar) return;
        
        // Convertir page DOM px → format fini mm (soustraire offset fond perdu pour x/y)
        const fpAf = getFondPerduOffset();
        setInputInToolbar(toolbar, 'contrainte-area-x', formatMmValue(pxToMm(xPx - fpAf.gauchePx)));
        setInputInToolbar(toolbar, 'contrainte-area-y', formatMmValue(pxToMm(yPx - fpAf.hautPx)));
        setInputInToolbar(toolbar, 'contrainte-area-w', formatMmValue(pxToMm(wPx)));
        setInputInToolbar(toolbar, 'contrainte-area-h', formatMmValue(pxToMm(hPx)));
    }
    
    /**
     * Met à jour la visibilité de l'area d'une zone.
     * L'area est visible uniquement quand la zone est sélectionnée.
     * 
     * @param {string} zoneId - ID de la zone
     * @param {boolean} visible - true pour afficher, false pour masquer
     * @returns {void}
     * 
     * @example
     * updateAreaVisibility('zone-1', true);  // Affiche l'area
     * updateAreaVisibility('zone-1', false); // Masque l'area
     */
    function updateAreaVisibility(zoneId, visible) {
        const areaEl = areaElements.get(zoneId);
        if (areaEl) {
            if (visible) {
                areaEl.classList.add('visible');
            } else {
                areaEl.classList.remove('visible');
            }
        }
    }

    /**
     * Met à jour la visibilité de toutes les areas en fonction de la sélection.
     * Seule l'area de la zone sélectionnée (en sélection unique) est visible.
     * En sélection multiple ou sans sélection, toutes les areas sont masquées.
     * 
     * @returns {void}
     * 
     * @example
     * // Après un changement de sélection
     * updateAreasVisibility();
     */
    function updateAreasVisibility() {
        // Masquer toutes les areas
        areaElements.forEach((areaEl, zoneId) => {
            areaEl.classList.remove('visible');
        });
        
        // Afficher l'area de la zone sélectionnée (uniquement en sélection unique)
        if (selectedZoneIds.length === 1) {
            const selectedId = selectedZoneIds[0];
            const areaEl = areaElements.get(selectedId);
            if (areaEl) {
                areaEl.classList.add('visible');
            }
        }
    }

    /**
     * Limites en pixels (coin haut-gauche de la zone) pour la ZonePersonnalisation de la page courante.
     * @param {number} zoneWidth
     * @param {number} zoneHeight
     * @returns {{minX: number, maxX: number, minY: number, maxY: number} | null}
     */
    function getZonePersonnalisationTopLeftBoundsPx(zoneWidth, zoneHeight) {
        const spec = getZonePersonnalisationSpecForPageIndex(documentState.currentPageIndex);
        if (!spec) return null;
        const fp = getFondPerduOffset();
        const left = mmToPx(spec.xMm) + fp.gauchePx;
        const top = mmToPx(spec.yMm) + fp.hautPx;
        const w = mmToPx(spec.largeurMm);
        const h = mmToPx(spec.hauteurMm);
        return {
            minX: left,
            maxX: left + w - zoneWidth,
            minY: top,
            maxY: top + h - zoneHeight
        };
    }

    /**
     * @param {number} zoneLeft
     * @param {number} zoneTop
     * @returns {{ maxWidth: number, maxHeight: number } | null}
     */
    function getZonePersonnalisationSizeCapPx(zoneLeft, zoneTop) {
        const spec = getZonePersonnalisationSpecForPageIndex(documentState.currentPageIndex);
        if (!spec) return null;
        const fp = getFondPerduOffset();
        const zLeft = mmToPx(spec.xMm) + fp.gauchePx;
        const zTop = mmToPx(spec.yMm) + fp.hautPx;
        const zW = mmToPx(spec.largeurMm);
        const zH = mmToPx(spec.hauteurMm);
        return {
            maxWidth: zLeft + zW - zoneLeft,
            maxHeight: zTop + zH - zoneTop
        };
    }

    /**
     * Intersecte les limites mm (minX/minY = coin haut-gauche, maxX/maxY = bords droit/bas autorisés pour la zone)
     * avec la ZonePersonnalisation de la page courante.
     * @param {{ minX: number, minY: number, maxX: number, maxY: number }} limitsMm
     */
    function intersectGeometryLimitsWithZonePersonnalisation(limitsMm) {
        const spec = getZonePersonnalisationSpecForPageIndex(documentState.currentPageIndex);
        if (!spec) return limitsMm;
        return {
            minX: Math.max(limitsMm.minX, spec.xMm),
            minY: Math.max(limitsMm.minY, spec.yMm),
            maxX: Math.min(limitsMm.maxX, spec.xMm + spec.largeurMm),
            maxY: Math.min(limitsMm.maxY, spec.yMm + spec.hauteurMm)
        };
    }

    /**
     * Calcule les limites de positionnement pour une zone en pixels.
     * Si la zone a une area définie, les limites sont celles de l'area.
     * Sinon, les limites sont celles de la page (avec marge de sécurité).
     * 
     * @param {string} zoneId - ID de la zone
     * @param {number} zoneWidth - Largeur actuelle de la zone en pixels
     * @param {number} zoneHeight - Hauteur actuelle de la zone en pixels
     * @returns {{minX: number, maxX: number, minY: number, maxY: number}} Limites en pixels
     * 
     * @example
     * const bounds = getAreaBoundsInPixels('zone-1', 200, 100);
     * // Avec area: { minX: 19, maxX: 200, minY: 19, maxY: 150 }
     * // Sans area: { minX: margin, maxX: pageWidth - margin - 200, ... }
     */
    function getAreaBoundsInPixels(zoneId, zoneWidth, zoneHeight) {
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        const fp = getFondPerduOffset();
        
        /** @type {{ minX: number, maxX: number, minY: number, maxY: number }} */
        let b;
        
        // Vérifier si la zone a une area valide (dimensions > 0)
        if (hasValidArea(zoneData)) {
            const area = zoneData.contrainte.geometrie.area;
            
            // Convertir l'area (format fini mm) en pixels page DOM (+ offset fond perdu)
            const areaXPx = mmToPx(area.xMm) + fp.gauchePx;
            const areaYPx = mmToPx(area.yMm) + fp.hautPx;
            const areaWPx = mmToPx(area.wMm);
            const areaHPx = mmToPx(area.hMm);
            
            // La zone doit rester entièrement dans l'area
            b = {
                minX: areaXPx,
                maxX: areaXPx + areaWPx - zoneWidth,
                minY: areaYPx,
                maxY: areaYPx + areaHPx - zoneHeight
            };
        } else {
            // Pas d'area : limites = format fini + marge de sécurité (en pixels page DOM)
            const margin = getSecurityMarginPx();
            const formatFiniWidthPx = mmToPx(getPageWidthMm());
            const formatFiniHeightPx = mmToPx(getPageHeightMm());
            
            b = {
                minX: fp.gauchePx + margin,
                maxX: fp.gauchePx + formatFiniWidthPx - margin - zoneWidth,
                minY: fp.hautPx + margin,
                maxY: fp.hautPx + formatFiniHeightPx - margin - zoneHeight
            };
        }
        
        const zpb = getZonePersonnalisationTopLeftBoundsPx(zoneWidth, zoneHeight);
        if (zpb) {
            b.minX = Math.max(b.minX, zpb.minX);
            b.maxX = Math.min(b.maxX, zpb.maxX);
            b.minY = Math.max(b.minY, zpb.minY);
            b.maxY = Math.min(b.maxY, zpb.maxY);
            if (b.maxX < b.minX) b.maxX = b.minX;
            if (b.maxY < b.minY) b.maxY = b.minY;
        }
        
        return b;
    }

    /**
     * Calcule la taille maximale possible pour une zone en pixels.
     * Si la zone a une area définie, la taille est limitée par l'area.
     * Sinon, la taille est limitée par la page (avec marge de sécurité).
     * 
     * @param {string} zoneId - ID de la zone
     * @param {number} zoneLeft - Position X actuelle de la zone en pixels
     * @param {number} zoneTop - Position Y actuelle de la zone en pixels
     * @returns {{maxWidth: number, maxHeight: number}} Taille maximale en pixels
     * 
     * @example
     * const maxSize = getAreaMaxSizeInPixels('zone-1', 50, 50);
     * // Avec area: { maxWidth: 300, maxHeight: 180 }
     * // Sans area: { maxWidth: pageWidth - margin - 50, maxHeight: ... }
     */
    function getAreaMaxSizeInPixels(zoneId, zoneLeft, zoneTop) {
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        const fp = getFondPerduOffset();
        
        /** @type {{ maxWidth: number, maxHeight: number }} */
        let result;
        
        // Vérifier si la zone a une area valide (dimensions > 0)
        if (hasValidArea(zoneData)) {
            const area = zoneData.contrainte.geometrie.area;
            
            // Convertir l'area (format fini mm) en pixels page DOM (+ offset fond perdu)
            const areaXPx = mmToPx(area.xMm) + fp.gauchePx;
            const areaYPx = mmToPx(area.yMm) + fp.hautPx;
            const areaWPx = mmToPx(area.wMm);
            const areaHPx = mmToPx(area.hMm);
            
            // Taille max = bord de l'area - position actuelle
            result = {
                maxWidth: areaXPx + areaWPx - zoneLeft,
                maxHeight: areaYPx + areaHPx - zoneTop
            };
        } else {
            // Pas d'area : bord droit/bas du format fini - marge - position actuelle
            const margin = getSecurityMarginPx();
            const formatFiniRightPx = fp.gauchePx + mmToPx(getPageWidthMm());
            const formatFiniBottomPx = fp.hautPx + mmToPx(getPageHeightMm());
            
            result = {
                maxWidth: formatFiniRightPx - margin - zoneLeft,
                maxHeight: formatFiniBottomPx - margin - zoneTop
            };
        }
        
        const zpCap = getZonePersonnalisationSizeCapPx(zoneLeft, zoneTop);
        if (zpCap) {
            result.maxWidth = Math.min(result.maxWidth, zpCap.maxWidth);
            result.maxHeight = Math.min(result.maxHeight, zpCap.maxHeight);
        }
        
        return result;
    }

    /**
     * Calcule les limites de géométrie en mm pour une zone spécifique.
     * Si la zone a une area définie, les limites sont celles de l'area.
     * Sinon, les limites sont celles de la page (avec marge de sécurité).
     * 
     * @param {string} zoneId - ID de la zone
     * @returns {{minX: number, minY: number, maxX: number, maxY: number}} Limites en mm
     * 
     * @example
     * const limits = getGeometryLimitsForZone('zone-1');
     * // Avec area: { minX: 5, minY: 5, maxX: 105, maxY: 65 }
     * // Sans area: { minX: margin, minY: margin, maxX: pageWidth - margin, ... }
     */
    function getGeometryLimitsForZone(zoneId) {
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        
        /** @type {{ minX: number, minY: number, maxX: number, maxY: number }} */
        let limits;
        
        // Vérifier si la zone a une area valide (dimensions > 0)
        if (hasValidArea(zoneData)) {
            const area = zoneData.contrainte.geometrie.area;
            
            limits = {
                minX: area.xMm,
                minY: area.yMm,
                maxX: area.xMm + area.wMm,
                maxY: area.yMm + area.hMm
            };
        } else {
            // Pas d'area : utiliser les limites de la page avec marge de sécurité
            const defaultLimits = getGeometryLimits();
            limits = {
                minX: defaultLimits.minX,
                minY: defaultLimits.minY,
                maxX: defaultLimits.maxX,
                maxY: defaultLimits.maxY
            };
        }
        
        return intersectGeometryLimitsWithZonePersonnalisation(limits);
    }

    /**
     * Vérifie si une zone a une area valide définie.
     * Une area est valide si elle existe ET a des dimensions > 0.
     * Nécessaire car WebDev sérialise toujours la structure area même si non définie
     * (avec des valeurs 0, 0, 0, 0).
     * 
     * @param {Object} zoneData - Données de la zone
     * @returns {boolean} true si area valide (wMm > 0 ET hMm > 0), false sinon
     * 
     * @example
     * // Area valide
     * hasValidArea({ contrainte: { geometrie: { area: { xMm: 10, yMm: 10, wMm: 100, hMm: 60 } } } }); // true
     * 
     * // Area invalide (valeurs par défaut WebDev)
     * hasValidArea({ contrainte: { geometrie: { area: { xMm: 0, yMm: 0, wMm: 0, hMm: 0 } } } }); // false
     * 
     * // Pas d'area
     * hasValidArea({ contrainte: { geometrie: { positionFixe: true } } }); // false
     */
    function hasValidArea(zoneData) {
        if (!zoneData || !zoneData.contrainte?.geometrie?.area) {
            return false;
        }
        const area = zoneData.contrainte.geometrie.area;
        return area.wMm > 0 && area.hMm > 0;
    }

    /**
     * Vérifie si les contraintes sont réellement définies ou si ce sont des valeurs par défaut.
     * Les contraintes sont considérées comme "non définies" si :
     * - L'objet constraints n'existe pas, est null ou n'est pas un objet
     * - L'objet constraints est vide (ne contient ni autorisations ni limites)
     * 
     * **Important** : Les contraintes sont considérées valides dès que `autorisations` OU `limites`
     * est présent, même si toutes les valeurs sont false/0 (interdiction totale volontaire).
     * Cela permet à WebDev d'interdire explicitement tous les types de zones.
     * 
     * @param {Object} constraints - Objet constraints du message WebDev
     * @returns {boolean} true si constraints contient autorisations ou limites, false sinon
     * 
     * @example
     * // Constraints valides (autorisations présent, même si tout false)
     * hasValidConstraints({ autorisations: { textQuill: false, image: false, qr: false, barcode: false } }); // true
     * 
     * // Constraints valides (limites présent, même si tout à 0)
     * hasValidConstraints({ limites: { textQuill: 0, image: 0, qr: 0, barcode: 0 } }); // true
     * 
     * // Constraints valides (interdiction totale explicite)
     * hasValidConstraints({ 
     *     autorisations: { textQuill: false, image: false, qr: false, barcode: false },
     *     limites: { textQuill: 0, image: 0, qr: 0, barcode: 0 }
     * }); // true
     * 
     * // Constraints invalides (objet vide)
     * hasValidConstraints({}); // false
     * 
     * // Pas de constraints
     * hasValidConstraints(null); // false
     * hasValidConstraints(undefined); // false
     */
    function hasValidConstraints(constraints) {
        // Pas de constraints du tout ou pas un objet
        if (!constraints || typeof constraints !== 'object') {
            return false;
        }
        
        // Si au moins autorisations OU limites est défini, les contraintes sont valides
        // Même si toutes les valeurs sont false/0 (interdiction totale volontaire)
        if (constraints.autorisations || constraints.limites) {
            return true;
        }
        
        // Pas de clé significative (objet vide ou autres propriétés non reconnues)
        return false;
    }

    /**
     * Applique les bornes de taille définies dans les contraintes géométriques.
     * Convertit les bornes de mm en pixels et contraint newW/newH dans les limites.
     * Les contraintes sont ignorées si leur valeur est 0 ou non définie.
     * 
     * @param {ContrainteGeometrie} geometrie - Objet contrainte.geometrie contenant les bornes
     * @param {number} [geometrie.minWMm] - Largeur minimum en mm (0 = pas de contrainte)
     * @param {number} [geometrie.maxWMm] - Largeur maximum en mm (0 = pas de contrainte)
     * @param {number} [geometrie.minHMm] - Hauteur minimum en mm (0 = pas de contrainte)
     * @param {number} [geometrie.maxHMm] - Hauteur maximum en mm (0 = pas de contrainte)
     * @param {number} newW - Nouvelle largeur demandée en pixels
     * @param {number} newH - Nouvelle hauteur demandée en pixels
     * @returns {{w: number, h: number}} Dimensions ajustées selon les contraintes
     * 
     * @example
     * // Pas de contrainte (valeurs = 0) → dimensions inchangées
     * applyContrainteBounds({ minWMm: 0, maxWMm: 0 }, 200, 100);
     * // → { w: 200, h: 100 }
     * 
     * @example
     * // Avec contraintes actives (valeurs > 0)
     * applyContrainteBounds({ minWMm: 50, maxWMm: 100 }, 200, 100);
     * // → { w: ~378 (100mm en px), h: 100 }
     */
    function applyContrainteBounds(geometrie, newW, newH) {
        let w = newW;
        let h = newH;
        
        if (!geometrie) return { w, h };
        
        // Appliquer les bornes de largeur (seulement si > 0)
        if (geometrie.minWMm > 0) {
            const minWPx = mmToPx(geometrie.minWMm);
            w = Math.max(w, minWPx);
        }
        if (geometrie.maxWMm > 0) {
            const maxWPx = mmToPx(geometrie.maxWMm);
            w = Math.min(w, maxWPx);
        }
        
        // Appliquer les bornes de hauteur (seulement si > 0)
        if (geometrie.minHMm > 0) {
            const minHPx = mmToPx(geometrie.minHMm);
            h = Math.max(h, minHPx);
        }
        if (geometrie.maxHMm > 0) {
            const maxHPx = mmToPx(geometrie.maxHMm);
            h = Math.min(h, maxHPx);
        }
        
        return { w, h };
    }

    /**
     * Mappe les clés WebDev vers les clés internes du Designer.
     * WebDev utilise des noms français (texte), le Designer utilise des noms techniques (textQuill).
     * @param {Object} obj - Objet à mapper (autorisations ou limites)
     * @returns {Object} Objet avec les clés mappées
     */
    function mapConstraintKeys(obj) {
        if (!obj || typeof obj !== 'object') return obj;
        
        const mapped = { ...obj };
        
        // Mapping : texte (WebDev) → textQuill (interne)
        if ('texte' in mapped && !('textQuill' in mapped)) {
            mapped.textQuill = mapped.texte;
            delete mapped.texte;
        }
        
        return mapped;
    }

    /**
     * Applique les contraintes de document reçues de WebDev.
     * Fusionne les contraintes reçues avec les valeurs par défaut.
     * Gère le mapping des clés WebDev (texte) vers les clés internes (textQuill).
     * 
     * @param {Object} constraints - Objet constraints reçu de WebDev
     * @param {ConstraintsAutorisations} [constraints.autorisations] - Autorisations par type
     * @param {ConstraintsLimites} [constraints.limites] - Limites de nombre par type
     * @returns {void}
     * 
     * @example
     * // Format WebDev (accepté)
     * applyConstraints({
     *     autorisations: { texte: true, image: false },
     *     limites: { texte: 1 }
     * });
     * 
     * @example
     * // Format interne (accepté aussi)
     * applyConstraints({
     *     autorisations: { textQuill: true, image: false },
     *     limites: { textQuill: 1 }
     * });
     */
    function applyConstraints(constraints) {
        // Vérifier si les contraintes sont réellement définies
        // (pas juste des valeurs par défaut WebDev : false/0)
        if (!hasValidConstraints(constraints)) {
            constraints = DEFAULT_CONSTRAINTS;
        }
        
        if (!constraints || typeof constraints !== 'object') {
            console.warn('⚠️ applyConstraints: constraints invalide');
            return;
        }
        
        // Mapper les clés WebDev vers les clés internes (texte → textQuill)
        const mappedAutorisations = mapConstraintKeys(constraints.autorisations);
        const mappedLimites = mapConstraintKeys(constraints.limites);
        
        // Conversion des VALEURS de limites WebDev → JS
        //   WebDev : -1 = illimité, 0 = interdit, >0 = max
        //   JS interne : null = illimité, 0 = interdit, >0 = max
        if (mappedLimites) {
            for (const key in mappedLimites) {
                if (mappedLimites[key] === -1) {
                    mappedLimites[key] = null;
                }
            }
        }
        
        // Fusionner avec les valeurs par défaut
        if (mappedAutorisations) {
            documentState.constraints.autorisations = {
                ...DEFAULT_CONSTRAINTS.autorisations,
                ...mappedAutorisations
            };
        }
        
        if (mappedLimites) {
            documentState.constraints.limites = {
                ...DEFAULT_CONSTRAINTS.limites,
                ...mappedLimites
            };
        }
        
        // ─── Override mode Template ──────────────────────────────────────
        // En mode création/modification de modèle, le créateur DOIT pouvoir
        // ajouter toutes les zones (textQuill, image, barcode, qr).
        // Les LIMITES stockées concernent l'utilisateur FINAL du tunnel et ne
        // s'appliquent pas au créateur (cf. isButtonVisible qui les bypass).
        // On les conserve telles quelles pour pré-remplir la popup et exporter.
        if (isTemplateMode()) {
            documentState.constraints.autorisations = {
                textQuill: true,
                image: true,
                qr: true,
                barcode: true
            };
            // QR : toujours 1 max (règle métier, cohérent mode tunnel)
            documentState.constraints.limites.qr = 1;
        }
        
        if (DEBUG) console.log('applyConstraints: Contraintes appliquées -',
            'autorisations:', documentState.constraints.autorisations,
            ', limites:', documentState.constraints.limites
        );
        
        // Mettre à jour la visibilité des boutons
        updateZoneButtonsVisibility();
        
    }

    // ─────────────────────────────── FIN SECTION 9 ────────────────────────────────

    // ═══════════════════════════════════════════════════════════════════════════════
    // SECTION 10 : CONTRAINTES REDIMENSIONNEMENT IMAGE
    // ═══════════════════════════════════════════════════════════════════════════════
    /**
     * Vérification et application des contraintes lors du redimensionnement.
     * Empêche l'agrandissement au-delà des limites de dimensions et DPI.
     * 
     * Fonctions principales :
     *   - checkImageResizeAllowed() : Vérifie si redimensionnement autorisé
     *   - calculateMaxDimensionsForDpi() : Calcule dimensions max pour DPI cible
     *   - showResizeConstraintMessage() : Affiche message de contrainte
     *   - showResizeConstraintMessageDebounced() : Version avec debounce
     * 
     * Dépendances :
     *   - getLargeurMaxImagePx(zoneData) / getHauteurMaxImagePx(zoneData) (Section 7)
     *   - calculateImageDpi() (Section 9)
     *   - DPI_MINIMUM (Section 7)
     */
    // ───────────────────────────────────────────────────────────────────────────────
    
    /**
     * Vérifie si un redimensionnement de zone image est autorisé.
     * Applique deux contraintes :
     * 1. Dimensions maximales (évite les zones trop grandes)
     * 2. DPI minimum (150 DPI, sauf pour les SVG)
     * 
     * @param {string} zoneId - Identifiant de la zone (ex: "zone-1")
     * @param {number} newWidth - Nouvelle largeur souhaitée en pixels
     * @param {number} newHeight - Nouvelle hauteur souhaitée en pixels
     * @returns {Object} Résultat de la vérification
     * @returns {boolean} returns.allowed - true si le redimensionnement est autorisé
     * @returns {string|null} returns.reason - Message d'erreur si refusé, null sinon
     * @returns {number|null} returns.maxWidth - Largeur maximale autorisée si refusé, null sinon
     * @returns {number|null} returns.maxHeight - Hauteur maximale autorisée si refusé, null sinon
     * 
     * @example
     * const result = checkImageResizeAllowed('zone-1', 500, 500);
     * if (!result.allowed) {
     *   console.log(result.reason); // "Dimensions maximum atteintes (70 × 90 mm)"
     *   // Utiliser result.maxWidth et result.maxHeight comme limites
     * }
     * 
     * @see DPI_MINIMUM - Seuil DPI minimum (150)
     * @see getLargeurMaxImagePx(zoneData) - Largeur maximale autorisée pour cette zone
     * @see getHauteurMaxImagePx(zoneData) - Hauteur maximale autorisée pour cette zone
     */
    function checkImageResizeAllowed(zoneId, newWidth, newHeight) {
        const zonesData = getCurrentPageZones();
        const zoneData = zonesData[zoneId];
        
        // Si ce n'est pas une zone image, autoriser
        if (!zoneData || zoneData.type !== 'image') {
            return { allowed: true, reason: null };
        }
        
        const source = zoneData.source || {};
        
        // Si pas d'image chargée, autoriser (pas de contrainte)
        if (!source.imageBase64 && !source.valeur) {
            return { allowed: true, reason: null };
        }
        
        // Si c'est un SVG, pas de contrainte DPI (mais contrainte dimensions)
        const isSvg = source.nomOriginal ? isSvgFile(source.nomOriginal) : false;
        
        // === CALCUL DES DEUX CONTRAINTES INDÉPENDAMMENT ===
        
        let dimensionConstraint = null;  // Contrainte dimensions max document
        let dpiConstraint = null;        // Contrainte DPI minimum
        
        // --- Calcul contrainte 1 : Dimensions maximales (override zone ou document) ---
        const maxWidthPx = getLargeurMaxImagePx(zoneData);
        const maxHeightPx = getHauteurMaxImagePx(zoneData);
        
        if (newWidth > maxWidthPx || newHeight > maxHeightPx) {
            // Calculer les dimensions maximales en conservant le ratio
            const currentRatio = newWidth / newHeight;
            let constrainedWidth = newWidth;
            let constrainedHeight = newHeight;
            
            if (newWidth > maxWidthPx) {
                constrainedWidth = maxWidthPx;
                constrainedHeight = maxWidthPx / currentRatio;
            }
            if (constrainedHeight > maxHeightPx) {
                constrainedHeight = maxHeightPx;
                constrainedWidth = maxHeightPx * currentRatio;
            }
            
            const maxWidthMm = Math.round(getLargeurMaxImageMm(zoneData));
            const maxHeightMm = Math.round(getHauteurMaxImageMm(zoneData));
            
            dimensionConstraint = {
                reason: `Dimensions maximum atteintes (${maxWidthMm} × ${maxHeightMm} mm)`,
                maxWidth: Math.floor(constrainedWidth),
                maxHeight: Math.floor(constrainedHeight)
            };
        }
        
        // --- Calcul contrainte 2 : DPI minimum (sauf SVG) ---
        if (!isSvg && source.largeurPx && source.hauteurPx) {
            const displayMode = zoneData.redimensionnement?.mode || 'ajuster';
            const dpi = calculateImageDpi(
                source.largeurPx,
                source.hauteurPx,
                newWidth,
                newHeight,
                displayMode
            );
            
            if (dpi < DPI_MINIMUM) {
                // Calculer les dimensions maximales pour 150 DPI
                const maxDimensions = calculateMaxDimensionsForDpi(
                    source.largeurPx,
                    source.hauteurPx,
                    DPI_MINIMUM,
                    displayMode,
                    newWidth / newHeight // Ratio actuel
                );
                
                dpiConstraint = {
                    reason: `Résolution minimum atteinte (${DPI_MINIMUM} dpi)`,
                    maxWidth: maxDimensions.width,
                    maxHeight: maxDimensions.height
                };
            }
        }
        
        // === RETOURNER LA CONTRAINTE LA PLUS RESTRICTIVE ===
        
        // Si aucune contrainte, autoriser
        if (!dimensionConstraint && !dpiConstraint) {
            return { allowed: true, reason: null };
        }
        
        // Si une seule contrainte, la retourner
        if (dimensionConstraint && !dpiConstraint) {
            return {
                allowed: false,
                reason: dimensionConstraint.reason,
                maxWidth: dimensionConstraint.maxWidth,
                maxHeight: dimensionConstraint.maxHeight
            };
        }
        
        if (dpiConstraint && !dimensionConstraint) {
            return {
                allowed: false,
                reason: dpiConstraint.reason,
                maxWidth: dpiConstraint.maxWidth,
                maxHeight: dpiConstraint.maxHeight
            };
        }
        
        // Si les deux contraintes existent, prendre la plus restrictive (plus petite surface)
        const dimArea = dimensionConstraint.maxWidth * dimensionConstraint.maxHeight;
        const dpiArea = dpiConstraint.maxWidth * dpiConstraint.maxHeight;
        
        if (dpiArea <= dimArea) {
            // DPI est plus restrictif
            return {
                allowed: false,
                reason: dpiConstraint.reason,
                maxWidth: dpiConstraint.maxWidth,
                maxHeight: dpiConstraint.maxHeight
            };
        } else {
            // Dimensions max est plus restrictif
            return {
                allowed: false,
                reason: dimensionConstraint.reason,
                maxWidth: dimensionConstraint.maxWidth,
                maxHeight: dimensionConstraint.maxHeight
            };
        }
    }
    
    /**
     * Calcule les dimensions optimales d'une zone image pour atteindre le DPI recommandé (200).
     * Utilisé après upload pour ajuster automatiquement la zone si l'image est trop petite.
     * 
     * @param {number} imagePxWidth - Largeur de l'image source en pixels
     * @param {number} imagePxHeight - Hauteur de l'image source en pixels
     * @param {number} currentZonePxWidth - Largeur actuelle de la zone en pixels
     * @param {number} currentZonePxHeight - Hauteur actuelle de la zone en pixels
     * @param {'initial'|'ajuster'|'couper'} [displayMode='ajuster'] - Mode d'affichage
     * @returns {{needsResize: boolean, newWidth: number, newHeight: number, currentDpi: number}}
     */
    function calculateOptimalZoneDimensions(imagePxWidth, imagePxHeight, currentZonePxWidth, currentZonePxHeight, displayMode = 'ajuster') {
        // Calculer le DPI actuel
        const currentDpi = calculateImageDpi(imagePxWidth, imagePxHeight, currentZonePxWidth, currentZonePxHeight, displayMode);
        
        // Si DPI >= recommandé, pas besoin de redimensionner
        if (currentDpi >= DPI_RECOMMENDED) {
            return {
                needsResize: false,
                newWidth: currentZonePxWidth,
                newHeight: currentZonePxHeight,
                currentDpi: currentDpi
            };
        }
        
        // Calculer les dimensions pour atteindre DPI_RECOMMENDED (200)
        // DPI = pixels_image / taille_pouces → taille_pouces = pixels_image / DPI
        // taille_mm = taille_pouces × 25.4
        // taille_px = taille_mm / MM_PER_PIXEL
        
        const optimalWidthMm = (imagePxWidth / DPI_RECOMMENDED) * 25.4;
        const optimalHeightMm = (imagePxHeight / DPI_RECOMMENDED) * 25.4;
        const optimalWidthPx = optimalWidthMm / MM_PER_PIXEL;
        const optimalHeightPx = optimalHeightMm / MM_PER_PIXEL;
        
        // Conserver le ratio de la zone actuelle si possible
        const currentRatio = currentZonePxWidth / currentZonePxHeight;
        const imageRatio = imagePxWidth / imagePxHeight;
        
        let newWidth, newHeight;
        
        if (displayMode === 'ajuster') {
            // Mode ajuster : la dimension limitante est celle qui donne le DPI le plus bas
            if (currentRatio > imageRatio) {
                // Zone plus large que l'image → hauteur est limitante
                newHeight = optimalHeightPx;
                newWidth = newHeight * currentRatio;
            } else {
                // Zone plus haute que l'image → largeur est limitante
                newWidth = optimalWidthPx;
                newHeight = newWidth / currentRatio;
            }
        } else if (displayMode === 'couper') {
            // Mode couper : on prend la plus grande dimension
            if (currentRatio > imageRatio) {
                newWidth = optimalWidthPx;
                newHeight = newWidth / currentRatio;
            } else {
                newHeight = optimalHeightPx;
                newWidth = newHeight * currentRatio;
            }
        } else {
            // Mode initial : utiliser les dimensions optimales directement
            newWidth = optimalWidthPx;
            newHeight = optimalHeightPx;
        }
        
        return {
            needsResize: true,
            newWidth: Math.round(newWidth),
            newHeight: Math.round(newHeight),
            currentDpi: currentDpi
        };
    }
    
    /**
     * Calcule les dimensions maximales d'une zone pour un DPI cible
     * @param {number} imagePxWidth - Largeur de l'image en pixels
     * @param {number} imagePxHeight - Hauteur de l'image en pixels
     * @param {number} targetDpi - DPI cible minimum
     * @param {string} displayMode - Mode d'affichage
     * @param {number} aspectRatio - Ratio largeur/hauteur de la zone
     * @returns {{width: number, height: number}}
     */
    function calculateMaxDimensionsForDpi(imagePxWidth, imagePxHeight, targetDpi, displayMode, aspectRatio) {
        // Formule inverse : à partir du DPI cible, calculer la taille max de la zone
        // DPI = pixels_image / (taille_affichée_en_pouces)
        // taille_affichée_en_pouces = pixels_image / DPI
        // taille_affichée_en_mm = (pixels_image / DPI) * 25.4
        // taille_affichée_en_px = taille_affichée_en_mm / MM_PER_PIXEL
        
        const maxWidthInches = imagePxWidth / targetDpi;
        const maxHeightInches = imagePxHeight / targetDpi;
        
        const maxWidthMm = maxWidthInches * 25.4;
        const maxHeightMm = maxHeightInches * 25.4;
        
        const maxWidthPx = maxWidthMm / MM_PER_PIXEL;
        const maxHeightPx = maxHeightMm / MM_PER_PIXEL;
        
        if (displayMode === 'ajuster') {
            // En mode ajuster, la zone peut être plus grande que l'image
            // car l'image est mise à l'échelle pour tenir dedans
            // On doit trouver la taille de zone qui donne exactement targetDpi
            
            // Si le ratio de la zone est plus large que l'image
            const imageRatio = imagePxWidth / imagePxHeight;
            
            if (aspectRatio > imageRatio) {
                // Zone plus large : la hauteur est contraignante
                return {
                    width: Math.floor(maxHeightPx * aspectRatio),
                    height: Math.floor(maxHeightPx)
                };
            } else {
                // Zone plus haute : la largeur est contraignante
                return {
                    width: Math.floor(maxWidthPx),
                    height: Math.floor(maxWidthPx / aspectRatio)
                };
            }
            
        } else if (displayMode === 'couper') {
            // En mode couper, l'image couvre toute la zone
            // La dimension la plus petite de l'image est utilisée
            const imageRatio = imagePxWidth / imagePxHeight;
            
            if (aspectRatio > imageRatio) {
                // Zone plus large : la largeur de l'image est utilisée
                return {
                    width: Math.floor(maxWidthPx),
                    height: Math.floor(maxWidthPx / aspectRatio)
                };
            } else {
                // Zone plus haute : la hauteur de l'image est utilisée
                return {
                    width: Math.floor(maxHeightPx * aspectRatio),
                    height: Math.floor(maxHeightPx)
                };
            }
            
        } else {
            // Mode initial : l'image garde sa taille native
            // La zone peut être de n'importe quelle taille
            return {
                width: 99999,
                height: 99999
            };
        }
    }
    
    /**
     * Affiche un message de contrainte (toast)
     * @param {string} message - Message à afficher
     */
    function showResizeConstraintMessage(message) {
        // Utiliser le système de toast existant (undo-redo-toast)
        const toast = document.getElementById('undo-redo-toast');
        if (toast) {
            toast.innerHTML = `
                <span class="material-icons toast-icon">block</span>
                <span>${message}</span>
            `;
            toast.className = 'undo-toast error show';
            
            setTimeout(() => {
                toast.classList.remove('show');
            }, 2000);
        }
    }
    
    // Variable pour éviter les messages répétitifs pendant le drag
    let lastConstraintMessage = '';
    let lastConstraintTime = 0;
    
    /**
     * Affiche un message de contrainte avec debounce
     * @param {string} message - Message à afficher
     */
    function showResizeConstraintMessageDebounced(message) {
        const now = Date.now();
        if (message === lastConstraintMessage && now - lastConstraintTime < 2000) {
            return; // Éviter les messages répétitifs
        }
        lastConstraintMessage = message;
        lastConstraintTime = now;
        showResizeConstraintMessage(message);
    }

    // ─────────────────────────────── FIN SECTION 10 ───────────────────────────────
    
    let zoneCounter = 0;
    let selectedZoneIds = []; // Tableau pour la sélection multiple
    let copiedZoneData = null; // Données de la zone copiée pour le copier-coller
    
    // Déclarer zoomLevel tôt pour qu'il soit disponible partout
    let zoomLevel = 1.0; // 100% par défaut

    // ═══════════════════════════════════════════════════════════════════════════════
    // SECTION 11 : SYSTÈME UNDO/REDO (Historique)
    // ═══════════════════════════════════════════════════════════════════════════════
    /**
     * Système d'historique pour annuler/rétablir les actions.
     * Gère les snapshots de l'état du document.
     * 
     * Objet principal :
     *   - historyManager : Gestionnaire d'états (states, currentIndex, flags)
     * 
     * Fonctions principales :
     *   - saveState() : Sauvegarde état après modification
     *   - undo() : Annule dernière action
     *   - redo() : Rétablit action annulée
     *   - restoreState() : Restaure depuis snapshot
     *   - updateHistoryUI() : Met à jour boutons et compteur
     *   - showUndoRedoToast() : Affiche notification
     * 
     * Dépendances :
     *   - documentState (Section 12)
     *   - loadCurrentPage() (Section 22)
     *   - btnUndo, btnRedo (Section 1)
     */
    // ───────────────────────────────────────────────────────────────────────────────

    const historyManager = {
        states: [],           // Tableau des snapshots de documentState
        currentIndex: -1,     // Position actuelle dans l'historique
        maxStates: 50,        // Limite mémoire
        isRestoring: false,   // Flag pour éviter de sauvegarder pendant une restauration
        isLoadingForm: false  // Flag pour éviter de sauvegarder pendant le chargement du formulaire
    };

    // Variable pour le debounce du contenu texte
    let contentSaveTimeout = null;

    // Timer de capture différée de l'« État initial » après un chargement
    //   WebDev (cf. captureInitialStateAfterLoad). Mémorisé pour pouvoir
    //   annuler une capture en attente si un nouveau 'load' arrive
    //   (idempotence : seul le dernier load finalisé pose l'index 0).
    let initialStateCaptureTimer = null;

    /**
     * Sauvegarde l'état actuel du document dans l'historique (pour Undo/Redo).
     * Crée un snapshot profond de documentState et l'ajoute à la pile d'historique.
     * 
     * Comportement :
     * - Synchronise d'abord les positions DOM → documentState
     * - Supprime les états "futurs" si on a fait des undo (branche abandonnée)
     * - Limite la taille de l'historique à maxStates (50 par défaut)
     * - Ne fait rien si isRestoring ou isLoadingForm est true
     * 
     * @fires updateHistoryUI - Met à jour les boutons Undo/Redo
     * 
     * @example
     * // Après une modification (création, déplacement, suppression de zone)
     * zonesData[id] = { type: 'textQuill', content: 'Nouveau' };
     * saveState(); // Snapshot pour pouvoir annuler
     * 
     * @see undo - Annuler la dernière action
     * @see redo - Rétablir l'action annulée
     * @see historyManager - Gestionnaire d'historique
     */
    function saveState(label) {
        // Base nommée de l'historique : chaque entrée porte un libellé en
        //   langage clair décrivant l'action. `label` est OPTIONNEL ; en son
        //   absence on retombe sur 'Modification' (aucune entrée anonyme).
        //   Ce libellé ne change RIEN au comportement de l'undo/redo : il
        //   n'est utilisé que pour le diagnostic et les infobulles UI.
        const stateLabel = (typeof label === 'string' && label.trim()) ? label.trim() : 'Modification';

        // Ne pas sauvegarder si on est en train de restaurer ou de charger le formulaire
        if (historyManager.isRestoring || historyManager.isLoadingForm) {
            return;
        }

        // L11 / V2.5 - Hook de mise à jour de la table champsExploites
        //   (et refresh des couleurs/corbeilles dans la popup). saveState
        //   est appelé après quasiment toute modification (frappe Quill
        //   debouncée, undo/redo, suppression/création de zone, etc.) →
        //   point d'ancrage central et économique.
        //   Le debounce interne à notifyChampsExploitesMayHaveChanged
        //   évite les recalculs redondants en cas d'appels rapprochés.
        try { notifyChampsExploitesMayHaveChanged(); } catch (e) { /* defensive */ }

        // Synchroniser les positions DOM vers documentState avant le snapshot
        const zonesData = getCurrentPageZones();
        for (const [id, data] of Object.entries(zonesData)) {
            const el = document.getElementById(id);
            if (el) {
                data.x = el.offsetLeft;
                data.y = el.offsetTop;
                data.w = el.offsetWidth;
                data.h = el.offsetHeight;
            }
        }
        
        // BUGFIX : persister le contenu Quill dans zonesData avant snapshot (Undo/Redo)
        // NE PAS persister en mode aperçu (le contenu affiché est fusionné, pas l'original)
        if (!previewState || !previewState.active) {
            persistTextQuillContentForSave(zonesData);
        }

        documentState.zoneCounter = zoneCounter;

        // Créer le snapshot (sérialisé UNE fois, réutilisé pour la garde
        //   anti-doublon ci-dessous afin d'éviter une double sérialisation).
        const snapshotStr = JSON.stringify(documentState);
        const snapshot = JSON.parse(snapshotStr);

        // Garde anti-doublon générique : si le snapshot est STRICTEMENT
        //   identique (contenu uniquement, libellé non comparé) au dernier
        //   état déjà présent dans la pile, on n'empile RIEN (vrai no-op : on
        //   ne touche ni à la pile, ni à la branche redo). Neutralise le
        //   doublon exact de l'insertion de champ (« Insertion du champ X »
        //   suivi du « Modification du texte » débouncé, contenu identique),
        //   ainsi que tout futur PUSH redondant (cascades, re-renders).
        //   Sans risque pour la frappe / mise en forme : celles-ci modifient
        //   réellement le contenu → snapshot différent → empilé normalement.
        if (historyManager.currentIndex >= 0) {
            const topEntry = historyManager.states[historyManager.currentIndex];
            if (topEntry && JSON.stringify(topEntry.snapshot) === snapshotStr) {
                return;
            }
        }

        // Supprimer les états "futurs" si on a fait des undo
        if (historyManager.currentIndex < historyManager.states.length - 1) {
            historyManager.states = historyManager.states.slice(0, historyManager.currentIndex + 1);
        }
        
        // Ajouter à l'historique — chaque entrée = { snapshot, label, ts }
        historyManager.states.push({ snapshot, label: stateLabel, ts: Date.now() });
        historyManager.currentIndex++;
        
        // Limiter la taille de l'historique
        if (historyManager.states.length > historyManager.maxStates) {
            historyManager.states.shift();
            historyManager.currentIndex--;
        }

        // Mettre à jour l'interface
        updateHistoryUI();
    }

    /**
     * Annule la dernière action (Undo).
     * Restaure l'état précédent depuis l'historique.
     * 
     * @returns {void}
     * @fires showUndoRedoToast - Affiche "Action annulée" ou "Rien à annuler"
     * @fires updateHistoryUI - Met à jour les boutons Undo/Redo
     * 
     * @example
     * // Raccourci clavier : Ctrl+Z
     * undo(); // Restaure l'état précédent
     * 
     * @see redo - Rétablir l'action annulée
     * @see saveState - Sauvegarder l'état courant
     */
    function undo() {
        if (historyManager.currentIndex <= 0) {
            showUndoRedoToast('Rien à annuler', 'error', 'block');
            return;
        }

        // Libellé de l'action ANNULÉE = celui de l'état qu'on quitte.
        const __labelAnnule = historyManager.states[historyManager.currentIndex]
            ? historyManager.states[historyManager.currentIndex].label : '';
        historyManager.currentIndex--;
        const __entry = historyManager.states[historyManager.currentIndex];
        restoreState(__entry.snapshot);
        updateHistoryUI();
        // Toast explicite : nomme l'action réellement annulée. Repli sur le
        //   message générique si le libellé est absent ou vaut 'Modification'.
        const __toastUndo = (__labelAnnule && __labelAnnule !== 'Modification')
            ? ('Annulé : ' + __labelAnnule)
            : 'Action annulée';
        showUndoRedoToast(__toastUndo, 'success', 'undo');
    }

    /**
     * Rétablit l'action annulée (Redo).
     * Restaure l'état suivant depuis l'historique (après un Undo).
     * 
     * @returns {void}
     * @fires showUndoRedoToast - Affiche "Action rétablie" ou "Rien à rétablir"
     * @fires updateHistoryUI - Met à jour les boutons Undo/Redo
     * 
     * @example
     * // Raccourci clavier : Ctrl+Y ou Ctrl+Shift+Z
     * redo(); // Restaure l'état suivant
     * 
     * @see undo - Annuler la dernière action
     * @see saveState - Sauvegarder l'état courant
     */
    function redo() {
        if (historyManager.currentIndex >= historyManager.states.length - 1) {
            showUndoRedoToast('Rien à rétablir', 'error', 'block');
            return;
        }

        historyManager.currentIndex++;
        const __entry = historyManager.states[historyManager.currentIndex];
        // Libellé de l'action RÉTABLIE = celui de l'état qu'on restaure.
        const __labelRetabli = __entry ? __entry.label : '';
        restoreState(__entry.snapshot);
        updateHistoryUI();
        // Toast explicite : nomme l'action réellement rétablie. Repli sur le
        //   message générique si le libellé est absent ou vaut 'Modification'.
        const __toastRedo = (__labelRetabli && __labelRetabli !== 'Modification')
            ? ('Rétabli : ' + __labelRetabli)
            : 'Action rétablie';
        showUndoRedoToast(__toastRedo, 'success', 'redo');
    }

    /**
     * Restaure un état complet du document depuis un snapshot d'historique.
     * Utilisée par undo() et redo() pour appliquer un état sauvegardé.
     * 
     * Étapes de restauration :
     * 1. Supprime toutes les zones du DOM
     * 2. Restaure documentState depuis le snapshot (copie profonde)
     * 3. Recharge la page courante (recrée les zones dans le DOM)
     * 4. Désélectionne toutes les zones
     * 5. Sauvegarde dans localStorage (sans ajouter à l'historique)
     * 
     * @param {DocumentState} snapshot - Snapshot de documentState à restaurer
     * @returns {void}
     * 
     * @see undo - Utilise cette fonction pour annuler
     * @see redo - Utilise cette fonction pour rétablir
     */
    function restoreState(snapshot) {
        historyManager.isRestoring = true;
        
        // AJOUT Phase 6 : Sauvegarder la sélection actuelle avant restauration
        const previousSelection = [...selectedZoneIds];

        // Popup « Champs de fusion » DÉCORRÉLÉE de la sélection : un undo/redo
        //   ne doit JAMAIS la fermer ni l'ouvrir de force. Le pipeline de
        //   sélection rejoué ci-dessous (deselectAll / updateSelectionUI →
        //   updateToolbarVisibility → closeFieldsPopup) écraserait son état
        //   d'ouverture. On mémorise donc les flags AVANT pour les RÉTABLIR
        //   à l'identique APRÈS le pipeline (cf. fin de fonction).
        const __popupIntentBefore = (typeof fieldsPopupUserIntent !== 'undefined') ? fieldsPopupUserIntent : false;
        const __popupShownBefore = (typeof fieldsPopupShown !== 'undefined') ? fieldsPopupShown : false;
        
        // 1. Supprimer toutes les zones du DOM et leurs areas
        document.querySelectorAll('.zone').forEach(el => el.remove());
        clearAllAreas();
        
        // 1b. Sauvegarder les données d'aperçu (ne doivent pas être perdues lors du Undo/Redo)
        const savedDonneesApercu = documentState.donneesApercu || [];
        // 1c. Sauvegarder les contraintes (ne doivent pas être perdues lors du Undo/Redo)
        const savedConstraints = documentState.constraints || { ...DEFAULT_CONSTRAINTS };
        
        // 2. Restaurer documentState
        documentState = JSON.parse(JSON.stringify(snapshot));
        zoneCounter = documentState.zoneCounter;
        
        // Synchroniser window.documentState (exposé pour debug console)
        window.documentState = documentState;

        // 2b. Restaurer les données d'aperçu
        documentState.donneesApercu = savedDonneesApercu;
        // 2c. Restaurer les contraintes
        documentState.constraints = savedConstraints;
        
        // 3. Recharger la page courante (recrée les zones dans le DOM)
        loadCurrentPage();
        
        // 4. Phase 6 : Restaurer la sélection pour les zones qui existent encore
        selectedZoneIds = [];
        const zonesData = getCurrentPageZones();
        
        previousSelection.forEach(zoneId => {
            // Vérifier si la zone existe dans l'état restauré ET dans le DOM
            if (zonesData[zoneId] && document.getElementById(zoneId)) {
                selectedZoneIds.push(zoneId);
                document.getElementById(zoneId).classList.add('selected');
            }
        });
        
        // 5. Mettre à jour l'interface selon la nouvelle sélection
        if (selectedZoneIds.length === 0) {
            // Aucune zone à resélectionner : désélection complète
            deselectAll();
        } else {
            // Mettre à jour l'UI pour refléter la sélection restaurée
            updateSelectionUI();
        }

        // 5b. RÉTABLIR l'état d'ouverture de la popup « Champs de fusion » tel
        //   qu'il était AVANT l'undo/redo. Le pipeline de sélection (étape 5)
        //   a pu appeler closeFieldsPopup() et forcer intent/shown à false :
        //   on réimpose l'état mémorisé, puis on resynchronise l'affichage via
        //   updateToolbarDataVisibility() (synchro PASSIVE = pas de recalcul
        //   contextuel, donc décorrélée de la sélection) → le bouton « Champs »
        //   reste cohérent avec l'état réel de la popup.
        try {
            if (typeof fieldsPopupUserIntent !== 'undefined') {
                fieldsPopupUserIntent = __popupIntentBefore;
            }
            if (typeof fieldsPopupShown !== 'undefined') {
                fieldsPopupShown = __popupShownBefore;
            }
            if (typeof updateToolbarDataVisibility === 'function') {
                updateToolbarDataVisibility();
            }
        } catch (e) { /* defensive */ }

        // 5c. RAFRAÎCHIR le contenu de la popup (liste + couleurs vert/rouge/gris)
        //   pour refléter le nouvel état restauré. Le scan des champs exploités
        //   dépend du contenu des zones, qui vient de changer. À faire que la
        //   popup soit ouverte ou fermée (pour qu'elle soit à jour si rouverte).
        try {
            if (typeof notifyChampsExploitesMayHaveChanged === 'function') {
                notifyChampsExploitesMayHaveChanged();
            }
        } catch (e) { /* defensive */ }

        // 6. Sauvegarder dans localStorage (sans ajouter à l'historique)
        saveToLocalStorage();
        
        historyManager.isRestoring = false;
    }

    /**
     * Affiche une notification toast pour Undo/Redo
     * @param {string} message - Message à afficher
     * @param {string} type - Type de toast ('success', 'error', ou vide)
     * @param {string} icon - Icône Material Icons (optionnel)
     */
    function showUndoRedoToast(message, type = 'success', icon = null) {
        if (!undoRedoToast) return;
        
        // Construire le contenu du toast
        let content = '';
        if (icon) {
            content += `<span class="material-icons toast-icon">${icon}</span>`;
        }
        content += `<span>${message}</span>`;
        
        undoRedoToast.innerHTML = content;
        undoRedoToast.className = 'undo-toast'; // Reset classes
        if (type) {
            undoRedoToast.classList.add(type);
        }
        undoRedoToast.classList.add('show');
        
        // Masquer après 1.5 secondes
        setTimeout(() => {
            undoRedoToast.classList.remove('show');
        }, 1500);
    }

    /**
     * Affiche un toast de notification pour les contraintes.
     * Utilisé pour les avertissements de validation (limites dépassées, etc.)
     * @param {string} message - Message à afficher
     * @param {string} type - Type de toast ('warning', 'info', 'error')
     * @param {string} [icon='warning'] - Icône Material Icons
     */
    function showConstraintToast(message, type = 'warning', icon = 'warning') {
        if (!undoRedoToast) return;
        
        const iconMap = {
            'warning': 'warning',
            'info': 'info',
            'error': 'error',
            'success': 'check_circle'
        };
        
        const finalIcon = icon || iconMap[type] || 'info';
        
        undoRedoToast.innerHTML = `
            <span class="material-icons toast-icon">${finalIcon}</span>
            <span>${message}</span>
        `;
        undoRedoToast.className = 'undo-toast';
        undoRedoToast.classList.add(type === 'warning' ? 'toast-theme-warning' : type);
        undoRedoToast.classList.add('show');
        
        setTimeout(() => {
            undoRedoToast.classList.remove('show');
        }, 2500);
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // NOTIFICATION MODAL — Popup thémée générique (erreurs, avertissements, infos)
    // ═══════════════════════════════════════════════════════════════════════════
    /**
     * Affiche une popup de notification thémée avec un ou plusieurs messages empilés.
     * Remplace les alert() navigateur par une modale élégante aux couleurs du thème.
     *
     * Chaque message est un objet { level, text, details? } :
     * - level : 'error' | 'warning' | 'info'
     * - text : Message principal affiché à l'utilisateur
     * - details : (optionnel) Tableau de chaînes pour les détails (ex: liste de fichiers ignorés)
     *
     * Le titre et l'icône de la popup sont déterminés automatiquement par le niveau
     * le plus élevé parmi les messages (error > warning > info).
     *
     * @param {Array<{level: 'error'|'warning'|'info', text: string, details?: string[]}>} messages - Messages à afficher
     * @param {Object} [options] - Options supplémentaires
     * @param {string} [options.title] - Titre personnalisé (sinon auto-déterminé)
     * @param {string} [options.buttonLabel='Fermer'] - Libellé du bouton
     * @param {Function} [options.onClose] - Callback appelé à la fermeture
     * @returns {void}
     *
     * @example
     * // Message unique
     * showNotification([
     *     { level: 'error', text: 'Le fichier ZIP est trop volumineux (350 Mo). Maximum autorisé : 200 Mo.' }
     * ]);
     *
     * @example
     * // Messages empilés après upload
     * showNotification([
     *     { level: 'info', text: 'Import réussi ! 150 images associées à des enregistrements.' },
     *     { level: 'warning', text: '30 image(s) sans correspondance dans la base de données.' },
     *     { level: 'warning', text: '5 fichier(s) ignoré(s).', details: ['logo.bmp (format non supporté)', 'test.tif (format non supporté)'] }
     * ]);
     */
    function showNotification(messages, options = {}) {
        if (!notificationModal || !notificationModalBody) return;

        // Déterminer le niveau le plus élevé pour le titre/icône
        const levelPriority = { error: 3, warning: 2, info: 1 };
        const levelConfig = {
            error:   { icon: 'error',        title: 'Erreur',        iconClass: 'notification-error' },
            warning: { icon: 'warning',      title: 'Avertissement', iconClass: 'notification-warning' },
            info:    { icon: 'check_circle', title: 'Information',   iconClass: 'notification-info' }
        };

        let maxLevel = 'info';
        for (const msg of messages) {
            if ((levelPriority[msg.level] || 0) > (levelPriority[maxLevel] || 0)) {
                maxLevel = msg.level;
            }
        }

        const config = levelConfig[maxLevel] || levelConfig.info;

        // Titre et icône
        if (notificationModalTitle) {
            notificationModalTitle.textContent = options.title || config.title;
        }
        if (notificationModalIcon) {
            notificationModalIcon.textContent = config.icon;
            notificationModalIcon.className = 'material-icons notification-modal-icon ' + config.iconClass;
        }

        // Construire le contenu (messages empilés)
        notificationModalBody.innerHTML = '';

        for (const msg of messages) {
            const itemConfig = levelConfig[msg.level] || levelConfig.info;
            const itemDiv = document.createElement('div');
            itemDiv.className = 'notification-item notification-' + msg.level;

            let itemHTML = '<span class="material-icons">' + itemConfig.icon + '</span>';
            itemHTML += '<div class="notification-item-content">';
            itemHTML += '<span>' + msg.text + '</span>';

            // Détails optionnels (liste)
            if (msg.details && Array.isArray(msg.details) && msg.details.length > 0) {
                itemHTML += '<ul class="notification-detail-list">';
                // Limiter à 10 détails visibles
                const maxDetails = 10;
                const displayed = msg.details.slice(0, maxDetails);
                for (const detail of displayed) {
                    itemHTML += '<li>' + detail + '</li>';
                }
                if (msg.details.length > maxDetails) {
                    itemHTML += '<li>… et ' + (msg.details.length - maxDetails) + ' autre(s)</li>';
                }
                itemHTML += '</ul>';
            }

            itemHTML += '</div>';
            itemDiv.innerHTML = itemHTML;
            notificationModalBody.appendChild(itemDiv);
        }

        // Bouton
        if (notificationModalOkBtn) {
            notificationModalOkBtn.textContent = options.buttonLabel || 'Fermer';
        }

        // Stocker le callback onClose
        notificationModal._onClose = options.onClose || null;

        // Afficher la modale
        notificationModal.classList.remove('hidden');
    }

    /**
     * Ferme la popup de notification.
     * Appelle le callback onClose si défini.
     * @returns {void}
     */
    function hideNotification() {
        if (!notificationModal) return;
        notificationModal.classList.add('hidden');

        // Appeler le callback si défini
        if (typeof notificationModal._onClose === 'function') {
            notificationModal._onClose();
            notificationModal._onClose = null;
        }
    }

    // --- Event listeners pour la modale Notification ---
    if (notificationModalOkBtn) {
        notificationModalOkBtn.addEventListener('click', hideNotification);
    }
    // Fermer en cliquant sur l'overlay
    if (notificationModal) {
        notificationModal.addEventListener('click', (e) => {
            if (e.target === notificationModal) {
                hideNotification();
            }
        });
    }

    // Exposer les fonctions globalement pour debug console et appel externe
    window.showNotification = showNotification;
    window.hideNotification = hideNotification;
    window.showUploadSummary = showUploadSummary;

    /**
     * Valide et contraint une valeur de contrainte aux limites du document.
     * Affiche un toast si la valeur a été corrigée.
     * @param {number} value - Valeur à valider (en mm)
     * @param {string} fieldType - Type de champ ('x', 'y', 'w', 'h', 'minW', 'minH', 'maxW', 'maxH')
     * @param {Object} [currentArea=null] - Valeurs actuelles de l'area {xMm, yMm, wMm, hMm} pour validation contextuelle
     * @returns {number} Valeur corrigée si nécessaire
     */
    function validateConstraintValue(value, fieldType, currentArea = null) {
        const limits = getGeometryLimits();
        const marginMm = limits.marginMm;
        const maxX = limits.maxX;
        const maxY = limits.maxY;
        const usableWidth = limits.pageWidthMm - (2 * marginMm);
        const usableHeight = limits.pageHeightMm - (2 * marginMm);
        
        let correctedValue = value;
        let wasCorrect = true;
        let message = '';
        
        switch (fieldType) {
            case 'x':
            case 'areaX':
                // X doit être >= marge
                if (value < marginMm) {
                    correctedValue = marginMm;
                    wasCorrect = false;
                    message = `X corrigé : minimum ${formatMmValue(marginMm)} mm (marge document)`;
                }
                // X + W ne doit pas dépasser maxX (si currentArea fourni)
                if (currentArea && value + currentArea.wMm > maxX) {
                    correctedValue = maxX - currentArea.wMm;
                    if (correctedValue < marginMm) correctedValue = marginMm;
                    wasCorrect = false;
                    message = `X corrigé : la zone dépasserait le document`;
                }
                break;
                
            case 'y':
            case 'areaY':
                // Y doit être >= marge
                if (value < marginMm) {
                    correctedValue = marginMm;
                    wasCorrect = false;
                    message = `Y corrigé : minimum ${formatMmValue(marginMm)} mm (marge document)`;
                }
                // Y + H ne doit pas dépasser maxY (si currentArea fourni)
                if (currentArea && value + currentArea.hMm > maxY) {
                    correctedValue = maxY - currentArea.hMm;
                    if (correctedValue < marginMm) correctedValue = marginMm;
                    wasCorrect = false;
                    message = `Y corrigé : la zone dépasserait le document`;
                }
                break;
                
            case 'w':
            case 'areaW':
                // Largeur doit être > 0 et <= largeur utilisable
                if (value <= 0) {
                    correctedValue = 1;
                    wasCorrect = false;
                    message = `Largeur corrigée : doit être > 0`;
                } else if (value > usableWidth) {
                    correctedValue = usableWidth;
                    wasCorrect = false;
                    message = `Largeur corrigée : maximum ${formatMmValue(usableWidth)} mm`;
                }
                // Si area, vérifier que X + W <= maxX
                if (currentArea && currentArea.xMm !== undefined && currentArea.xMm + value > maxX) {
                    correctedValue = maxX - currentArea.xMm;
                    wasCorrect = false;
                    message = `Largeur corrigée : dépassement du document`;
                }
                break;
                
            case 'minW':
            case 'maxW':
                // Largeur doit être > 0
                if (value <= 0) {
                    correctedValue = 1;
                    wasCorrect = false;
                    message = `Largeur corrigée : doit être > 0`;
                } else if (currentArea && currentArea.zoneXMm !== undefined) {
                    // Calculer la limite max selon le contexte
                    let maxAllowedWidth;
                    
                    if (currentArea.areaWMm !== undefined) {
                        // Area active : limite = bord droit area - position zone
                        maxAllowedWidth = (currentArea.areaXMm + currentArea.areaWMm) - currentArea.zoneXMm;
                        if (value > maxAllowedWidth) {
                            correctedValue = maxAllowedWidth;
                            wasCorrect = false;
                            message = `Largeur corrigée : maximum ${formatMmValue(maxAllowedWidth)} mm (limite area)`;
                        }
                    } else {
                        // Pas d'area : limite = bord droit document - position zone
                        maxAllowedWidth = maxX - currentArea.zoneXMm;
                        if (value > maxAllowedWidth) {
                            correctedValue = maxAllowedWidth;
                            wasCorrect = false;
                            message = `Largeur corrigée : maximum ${formatMmValue(maxAllowedWidth)} mm (limite document)`;
                        }
                    }
                } else if (value > usableWidth) {
                    // Fallback : limite = largeur utilisable
                    correctedValue = usableWidth;
                    wasCorrect = false;
                    message = `Largeur corrigée : maximum ${formatMmValue(usableWidth)} mm`;
                }
                break;
                
            case 'h':
            case 'areaH':
                // Hauteur doit être > 0 et <= hauteur utilisable
                if (value <= 0) {
                    correctedValue = 1;
                    wasCorrect = false;
                    message = `Hauteur corrigée : doit être > 0`;
                } else if (value > usableHeight) {
                    correctedValue = usableHeight;
                    wasCorrect = false;
                    message = `Hauteur corrigée : maximum ${formatMmValue(usableHeight)} mm`;
                }
                // Si area, vérifier que Y + H <= maxY
                if (currentArea && currentArea.yMm !== undefined && currentArea.yMm + value > maxY) {
                    correctedValue = maxY - currentArea.yMm;
                    wasCorrect = false;
                    message = `Hauteur corrigée : dépassement du document`;
                }
                break;
                
            case 'minH':
            case 'maxH':
                // Hauteur doit être > 0
                if (value <= 0) {
                    correctedValue = 1;
                    wasCorrect = false;
                    message = `Hauteur corrigée : doit être > 0`;
                } else if (currentArea && currentArea.zoneYMm !== undefined) {
                    // Calculer la limite max selon le contexte
                    let maxAllowedHeight;
                    
                    if (currentArea.areaHMm !== undefined) {
                        // Area active : limite = bord bas area - position zone
                        maxAllowedHeight = (currentArea.areaYMm + currentArea.areaHMm) - currentArea.zoneYMm;
                        if (value > maxAllowedHeight) {
                            correctedValue = maxAllowedHeight;
                            wasCorrect = false;
                            message = `Hauteur corrigée : maximum ${formatMmValue(maxAllowedHeight)} mm (limite area)`;
                        }
                    } else {
                        // Pas d'area : limite = bord bas document - position zone
                        maxAllowedHeight = maxY - currentArea.zoneYMm;
                        if (value > maxAllowedHeight) {
                            correctedValue = maxAllowedHeight;
                            wasCorrect = false;
                            message = `Hauteur corrigée : maximum ${formatMmValue(maxAllowedHeight)} mm (limite document)`;
                        }
                    }
                } else if (value > usableHeight) {
                    // Fallback : limite = hauteur utilisable
                    correctedValue = usableHeight;
                    wasCorrect = false;
                    message = `Hauteur corrigée : maximum ${formatMmValue(usableHeight)} mm`;
                }
                break;
        }
        
        // Afficher un toast si correction effectuée
        if (!wasCorrect && message) {
            showConstraintToast(message, 'warning', 'straighten');
        }
        
        return Math.round(correctedValue * 10) / 10; // Arrondi à 1 décimale
    }

    /**
     * Valide et corrige les contraintes de taille min/max d'une zone après un déplacement.
     * Vérifie que les tailles min/max ne feraient pas dépasser la zone du document ou de l'area.
     * @param {string} zoneId - ID de la zone à valider
     * @returns {void}
     */
    function validateAndCorrectSizeConstraints(zoneId) {
        const zoneEl = document.getElementById(zoneId);
        const zones = getCurrentPageZones();
        const zoneData = zones[zoneId];
        
        if (!zoneEl || !zoneData || !zoneData.contrainte || !zoneData.contrainte.geometrie) return;
        
        const geometrie = zoneData.contrainte.geometrie;
        const limits = getGeometryLimits();
        const maxX = limits.maxX;
        const maxY = limits.maxY;
        
        // Position actuelle en format fini mm (DOM px - offset fond perdu)
        const fpVc = getFondPerduOffset();
        const zoneXMm = pxToMm(zoneEl.offsetLeft - fpVc.gauchePx);
        const zoneYMm = pxToMm(zoneEl.offsetTop - fpVc.hautPx);
        
        // Calculer les limites selon le contexte (area ou document)
        let maxAllowedWidth, maxAllowedHeight;
        
        if (geometrie.area) {
            maxAllowedWidth = (geometrie.area.xMm + geometrie.area.wMm) - zoneXMm;
            maxAllowedHeight = (geometrie.area.yMm + geometrie.area.hMm) - zoneYMm;
        } else {
            maxAllowedWidth = maxX - zoneXMm;
            maxAllowedHeight = maxY - zoneYMm;
        }
        
        // Arrondir les limites à 1 décimale
        maxAllowedWidth = Math.round(maxAllowedWidth * 10) / 10;
        maxAllowedHeight = Math.round(maxAllowedHeight * 10) / 10;
        
        let corrected = false;
        let corrections = [];
        
        // Corriger la taille minimum si nécessaire (propriétés: minWMm, minHMm)
        if (geometrie.minWMm !== undefined && geometrie.minWMm > maxAllowedWidth) {
            geometrie.minWMm = Math.round(Math.max(1, maxAllowedWidth) * 10) / 10;
            corrected = true;
            corrections.push(`largeur min → ${geometrie.minWMm.toFixed(1).replace('.', ',')} mm`);
        }
        if (geometrie.minHMm !== undefined && geometrie.minHMm > maxAllowedHeight) {
            geometrie.minHMm = Math.round(Math.max(1, maxAllowedHeight) * 10) / 10;
            corrected = true;
            corrections.push(`hauteur min → ${geometrie.minHMm.toFixed(1).replace('.', ',')} mm`);
        }
        
        // Corriger la taille maximum si nécessaire (propriétés: maxWMm, maxHMm)
        if (geometrie.maxWMm !== undefined && geometrie.maxWMm > maxAllowedWidth) {
            geometrie.maxWMm = Math.round(Math.max(1, maxAllowedWidth) * 10) / 10;
            corrected = true;
            corrections.push(`largeur max → ${geometrie.maxWMm.toFixed(1).replace('.', ',')} mm`);
        }
        if (geometrie.maxHMm !== undefined && geometrie.maxHMm > maxAllowedHeight) {
            geometrie.maxHMm = Math.round(Math.max(1, maxAllowedHeight) * 10) / 10;
            corrected = true;
            corrections.push(`hauteur max → ${geometrie.maxHMm.toFixed(1).replace('.', ',')} mm`);
        }
        
        // Mettre à jour les champs de la toolbar si corrections effectuées
        if (corrected) {
            // Mapper le type de zone vers le type de toolbar
            let toolbarType = zoneData.type;
            if (toolbarType === 'qr') toolbarType = 'qrcode';
            if (toolbarType === 'text') toolbarType = 'textQuill';
            
            // Trouver la toolbar visible pour ce type de zone (attribut data-toolbar-for)
            const toolbar = document.querySelector(`.toolbar-poc[data-toolbar-for*="${toolbarType}"]`);
            
            
            if (toolbar) {
                // Mettre à jour les champs avec les valeurs arrondies
                if (geometrie.minWMm !== undefined) {
                    const inputMinW = toolbar.querySelector('#contrainte-min-w');
                    if (inputMinW) {
                        inputMinW.value = geometrie.minWMm.toFixed(1).replace('.', ',');
                    }
                }
                if (geometrie.minHMm !== undefined) {
                    const inputMinH = toolbar.querySelector('#contrainte-min-h');
                    if (inputMinH) {
                        inputMinH.value = geometrie.minHMm.toFixed(1).replace('.', ',');
                    }
                }
                if (geometrie.maxWMm !== undefined) {
                    const inputMaxW = toolbar.querySelector('#contrainte-max-w');
                    if (inputMaxW) {
                        inputMaxW.value = geometrie.maxWMm.toFixed(1).replace('.', ',');
                    }
                }
                if (geometrie.maxHMm !== undefined) {
                    const inputMaxH = toolbar.querySelector('#contrainte-max-h');
                    if (inputMaxH) {
                        inputMaxH.value = geometrie.maxHMm.toFixed(1).replace('.', ',');
                    }
                }
            }
            
            // Afficher un toast avec les corrections
            showConstraintToast(`Contraintes ajustées : ${corrections.join(', ')}`, 'warning', 'straighten');
            
            // Sauvegarder les modifications
            saveToLocalStorage();
        }
    }

    /**
     * Calcule les valeurs initiales de l'area centrée autour de la zone.
     * Contraint l'area aux limites du document.
     * @param {number} zoneXMm - Position X de la zone en mm
     * @param {number} zoneYMm - Position Y de la zone en mm
     * @param {number} zoneWMm - Largeur de la zone en mm
     * @param {number} zoneHMm - Hauteur de la zone en mm
     * @returns {Object} {xMm, yMm, wMm, hMm} - Valeurs de l'area
     */
    function calculateInitialAreaValues(zoneXMm, zoneYMm, zoneWMm, zoneHMm) {
        const limits = getGeometryLimits();
        const marginMm = limits.marginMm;
        const maxX = limits.maxX;
        const maxY = limits.maxY;
        
        // Calculer area centrée : zone au milieu avec marge de 50% de chaque côté
        let areaX = zoneXMm - (zoneWMm / 2);
        let areaY = zoneYMm - (zoneHMm / 2);
        let areaW = zoneWMm * 2;
        let areaH = zoneHMm * 2;
        
        // Contraindre aux limites du document
        
        // 1. S'assurer que X >= marge
        if (areaX < marginMm) {
            areaX = marginMm;
        }
        
        // 2. S'assurer que Y >= marge
        if (areaY < marginMm) {
            areaY = marginMm;
        }
        
        // 3. S'assurer que X + W <= maxX
        if (areaX + areaW > maxX) {
            // D'abord essayer de réduire la largeur
            areaW = maxX - areaX;
            // Si la largeur devient trop petite, décaler X
            if (areaW < zoneWMm) {
                areaW = zoneWMm;
                areaX = maxX - areaW;
                if (areaX < marginMm) areaX = marginMm;
            }
        }
        
        // 4. S'assurer que Y + H <= maxY
        if (areaY + areaH > maxY) {
            // D'abord essayer de réduire la hauteur
            areaH = maxY - areaY;
            // Si la hauteur devient trop petite, décaler Y
            if (areaH < zoneHMm) {
                areaH = zoneHMm;
                areaY = maxY - areaH;
                if (areaY < marginMm) areaY = marginMm;
            }
        }
        
        return {
            xMm: Math.round(areaX * 10) / 10,
            yMm: Math.round(areaY * 10) / 10,
            wMm: Math.round(areaW * 10) / 10,
            hMm: Math.round(areaH * 10) / 10
        };
    }

    /**
     * Libellé de l'action qui serait ANNULÉE par un Undo (= libellé de
     * l'état courant). Retourne null s'il n'y a rien à annuler.
     * @returns {string|null}
     */
    function getUndoLabel() {
        if (historyManager.currentIndex <= 0) return null;
        const entry = historyManager.states[historyManager.currentIndex];
        return (entry && entry.label) ? entry.label : null;
    }

    /**
     * Libellé de l'action qui serait RÉTABLIE par un Redo (= libellé de
     * l'état suivant). Retourne null s'il n'y a rien à rétablir.
     * @returns {string|null}
     */
    function getRedoLabel() {
        if (historyManager.currentIndex >= historyManager.states.length - 1) return null;
        const entry = historyManager.states[historyManager.currentIndex + 1];
        return (entry && entry.label) ? entry.label : null;
    }

    /**
     * Met à jour l'interface des boutons et compteur d'historique
     */
    function updateHistoryUI() {
        const canUndo = historyManager.currentIndex > 0;
        const canRedo = historyManager.currentIndex < historyManager.states.length - 1;
        
        // Mettre à jour l'état des boutons
        if (btnUndo) btnUndo.disabled = !canUndo;
        if (btnRedo) btnRedo.disabled = !canRedo;

        // Infobulles dynamiques : « Annuler : <libellé> » / « Rétablir : <libellé> ».
        //   Si rien à annuler/rétablir → infobulle neutre. N'affecte pas le
        //   comportement (l'état désactivé reste géré par .disabled ci-dessus).
        if (btnUndo) {
            const lbl = getUndoLabel();
            btnUndo.title = lbl ? ('Annuler : ' + lbl) : 'Annuler';
        }
        if (btnRedo) {
            const lbl = getRedoLabel();
            btnRedo.title = lbl ? ('Rétablir : ' + lbl) : 'Rétablir';
        }
        
        // Mettre à jour le compteur
        if (historyPositionEl) {
            historyPositionEl.textContent = historyManager.currentIndex + 1;
        }
        if (historyTotalEl) {
            historyTotalEl.textContent = historyManager.states.length;
        }
    }

    /**
     * Réinitialise la pile d'historique et capture le document fraîchement
     * chargé depuis WebDev comme UNIQUE état initial (index 0).
     *
     * Pourquoi : `saveState('État initial')` du boot iframe est prématuré
     * (capture l'état localStorage pré-WebDev, zones système non finalisées).
     * Ici, on repose une base propre APRÈS le chargement WebDev stabilisé.
     * Réutilise le motif des resets (resetCurrentPage / resetAllPages) :
     * states=[] / currentIndex=-1 / saveState → currentIndex=0 → undo grisé.
     *
     * @returns {void}
     */
    function captureInitialStateAfterLoad() {
        try {
            historyManager.states = [];
            historyManager.currentIndex = -1;
            // Le snapshot pris ici reflète le documentState final (zones
            //   système positionnées, datamatrix dimensionnée, images placées).
            saveState('État initial');
        } catch (e) { /* defensive */ }
    }

    /**
     * Planifie la capture de l'état initial APRÈS la fin réelle des
     * traitements asynchrones internes de `loadFromWebDev` (régénération
     * datamatrix ~+100 ms, images dynamiques ~+150 ms). On utilise un délai
     * de repli postérieur au plus long timeout interne (150 ms) avec marge
     * de sécurité — voir récap pour la justification du choix « délai » vs
     * « signal ». Idempotent : un nouvel appel annule la capture en attente.
     *
     * @returns {void}
     */
    function scheduleInitialStateCapture() {
        try {
            if (initialStateCaptureTimer) {
                clearTimeout(initialStateCaptureTimer);
            }
        } catch (e) { /* defensive */ }
        initialStateCaptureTimer = setTimeout(() => {
            initialStateCaptureTimer = null;
            captureInitialStateAfterLoad();
        }, 250);
    }

    // ─────────────────────────────── FIN SECTION 11 ───────────────────────────────

    // ═══════════════════════════════════════════════════════════════════════════════
    // SECTION 12 : ÉTAT DU DOCUMENT ET HELPERS
    // ═══════════════════════════════════════════════════════════════════════════════
    /**
     * Structure centrale de données et fonctions d'accès.
     * Gère les formats de document et les dimensions de page.
     * 
     * Constantes :
     *   - DOCUMENT_FORMATS : Formats prédéfinis en pixels
     *   - DOCUMENT_FORMATS_MM : Formats prédéfinis en mm
     * 
     * Objet principal :
     *   - documentState : État complet du document (pages, zones, compteurs)
     * 
     * Fonctions principales :
     *   - getCurrentPage() : Page courante
     *   - getCurrentPageZones() : Zones de la page courante
     *   - getPageWidth/Height() : Dimensions en pixels
     *   - getPageWidthMm/HeightMm() : Dimensions en mm
     *   - applyPageDimensions() : Applique au DOM
     *   - getCenterOfView() : Centre de la vue actuelle
     * 
     * Dépendances :
     *   - a4Page (Section 1)
     *   - pxToMm() (Section 6)
     */
    // ───────────────────────────────────────────────────────────────────────────────

    // Formats prédéfinis (dimensions en pixels à 96 DPI)
    const DOCUMENT_FORMATS = {
        'A4': { width: 794, height: 1123, name: 'A4' },
        'A3': { width: 1123, height: 1587, name: 'A3' },
        'A5': { width: 559, height: 794, name: 'A5' },
        'Letter': { width: 816, height: 1056, name: 'Letter (US)' },
        'Legal': { width: 816, height: 1344, name: 'Legal (US)' }
    };

    // Formats prédéfinis en mm (dimensions EXACTES sans conversion)
    const DOCUMENT_FORMATS_MM = {
        'A4': { widthMm: 210, heightMm: 297, name: 'A4' },
        'A3': { widthMm: 297, heightMm: 420, name: 'A3' },
        'A5': { widthMm: 148, heightMm: 210, name: 'A5' },
        'Letter': { widthMm: 215.9, heightMm: 279.4, name: 'Letter (US)' },
        'Legal': { widthMm: 215.9, heightMm: 355.6, name: 'Legal (US)' }
    };

    // Format par défaut (A4)
    const DEFAULT_FORMAT = 'A4';

    /**
     * Contraintes par défaut du document (tout autorisé, pas de limites)
     * @type {DocumentConstraints}
     */
    const DEFAULT_CONSTRAINTS = {
        autorisations: {
            textQuill: true,
            image: true,
            qr: true,
            barcode: true
        },
        limites: {
            textQuill: null,
            image: null,
            qr: 1,        // Un seul QR interactif par document (déjà implémenté)
            barcode: null
        }
    };

    /**
     * Snapshot du nombre de zones par type au moment du chargement du document.
     * Sert de référence pour la sémantique "zones SUPPLÉMENTAIRES" des limites :
     * en mode standard, l'utilisateur du tunnel peut ajouter au plus
     *   limites[type] zones AU-DELÀ de celles déjà présentes dans le modèle.
     *
     * Convention valeurs limites JS :
     *   - null      : illimité (équivalent WebDev -1)
     *   - 0         : interdit (aucun ajout possible au-delà du modèle)
     *   - >0        : nombre maximum d'ajouts au-delà du modèle
     *
     * Mis à jour dans loadFromWebDev() après chargement complet des zones.
     * @type {{textQuill:number, image:number, qr:number, barcode:number}}
     */
    let initialZoneCounts = { textQuill: 0, image: 0, qr: 0, barcode: 0 };

    // --- STOCKAGE DES DONNÉES (Le "Cerveau") ---
    // Nouvelle structure hiérarchique multipage avec dimensions
    let documentState = {
        currentPageIndex: 0, // 0 = Recto
        pages: [
            {
                id: 'page-1',
                name: 'Recto',
                image: 'a4_template_recto.jpg',
                format: DEFAULT_FORMAT, // Format de la page
                width: DOCUMENT_FORMATS[DEFAULT_FORMAT].width, // Largeur en pixels
                height: DOCUMENT_FORMATS[DEFAULT_FORMAT].height, // Hauteur en pixels
                zones: {}
            },
            {
                id: 'page-2',
                name: 'Verso',
                image: 'a4_template_verso.jpg',
                format: DEFAULT_FORMAT,
                width: DOCUMENT_FORMATS[DEFAULT_FORMAT].width,
                height: DOCUMENT_FORMATS[DEFAULT_FORMAT].height,
                zones: {}
            }
        ],
        zoneCounter: 0, // Compteur global pour ID uniques
        /**
         * Données d'échantillon pour l'aperçu de fusion
         * @type {EchantillonData[]}
         */
        donneesApercu: [],
        /**
         * Contraintes du document (autorisations et limites)
         * @type {DocumentConstraints}
         */
        constraints: { ...DEFAULT_CONSTRAINTS },
        /** @type {boolean} Aligné sur WebDev ChampsFusionInterdit (enveloppe sans fenêtre, documents intérieurs) */
        champsFusionInterdit: false
    };

    /**
     * Mode de fonctionnement du Designer.
     * - 'standard' : Utilisateur final, contraintes appliquées (sections grisées)
     * - 'template' : Créateur de template, peut définir les contraintes
     * @type {'standard'|'template'}
     */
    let designerMode = 'standard';

    /**
     * Définit le mode de fonctionnement du Designer.
     * @param {'standard'|'template'} mode - Le mode à activer
     * @returns {void}
     */
    function setDesignerMode(mode) {
        if (mode !== 'standard' && mode !== 'template') {
            console.warn(`⚠️ Mode invalide "${mode}", utilisation de "standard" par défaut`);
            mode = 'standard';
        }
        designerMode = mode;
        
        // Mettre à jour la classe CSS sur le body pour les styles conditionnels
        if (designerMode === 'template') {
            document.body.classList.add('template-mode');
            document.body.classList.remove('standard-mode');
        } else {
            document.body.classList.remove('template-mode');
            document.body.classList.add('standard-mode');
        }
        
        // Mettre à jour la visibilité des onglets Contraintes (sera implémenté en Phase 3)
        if (typeof updateToolbarTabsVisibility === 'function') {
            updateToolbarTabsVisibility();
        }
    }

    /**
     * Retourne le mode de fonctionnement actuel du Designer.
     * @returns {'standard'|'template'} Le mode actuel
     */
    function getDesignerMode() {
        return designerMode;
    }

    /**
     * Vérifie si le Designer est en mode Template.
     * @returns {boolean} true si mode template, false sinon
     */
    function isTemplateMode() {
        return designerMode === 'template';
    }

    /**
     * Bascule vers un onglet spécifique dans une toolbar.
     * @param {HTMLElement} toolbar - L'élément toolbar parent
     * @param {string} tabName - Le nom de l'onglet ('personnalisation' ou 'contraintes')
     * @returns {void}
     */
    function switchToolbarTab(toolbar, tabName) {
        if (!toolbar) return;
        
        // Mettre à jour les boutons d'onglets
        const tabs = toolbar.querySelectorAll('.toolbar-tab-poc');
        tabs.forEach(tab => {
            if (tab.dataset.tab === tabName) {
                tab.classList.add('active');
            } else {
                tab.classList.remove('active');
            }
        });
        
        // Mettre à jour le contenu des onglets
        const contents = toolbar.querySelectorAll('.toolbar-tab-content-poc');
        contents.forEach(content => {
            if (content.dataset.tabContent === tabName) {
                content.classList.add('active');
            } else {
                content.classList.remove('active');
            }
        });
    }

    /**
     * Met à jour la visibilité des onglets Contraintes selon le mode Designer.
     * En mode Standard, l'onglet Contraintes est masqué.
     * En mode Template, l'onglet Contraintes est visible.
     * @returns {void}
     */
    function updateToolbarTabsVisibility() {
        const constraintsTabs = document.querySelectorAll('.toolbar-tab-poc[data-tab="contraintes"]');
        const isTemplate = isTemplateMode();
        
        constraintsTabs.forEach(tab => {
            if (isTemplate) {
                tab.classList.remove('hidden');
            } else {
                tab.classList.add('hidden');
                // Si on passe en mode standard et que l'onglet Contraintes était actif,
                // basculer vers Personnalisation
                if (tab.classList.contains('active')) {
                    const toolbar = tab.closest('.toolbar-poc');
                    if (toolbar) {
                        switchToolbarTab(toolbar, 'personnalisation');
                    }
                }
            }
        });
        
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Fonctions de gestion de l'onglet Contraintes
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * Retourne la toolbar actuellement visible pour le type de zone donné.
     * @param {string} zoneType - Type de zone ('textQuill', 'image', 'barcode', 'qr')
     * @returns {HTMLElement|null} L'élément toolbar ou null
     */
    function getActiveToolbarForType(zoneType) {
        const toolbarMap = {
            'textQuill': 'quill-toolbar',
            'text': 'quill-toolbar',
            'image': 'image-toolbar',
            'barcode': 'barcode-toolbar',
            'qr': 'qrcode-toolbar'
        };
        const toolbarId = toolbarMap[zoneType];
        return toolbarId ? document.getElementById(toolbarId) : null;
    }

    /**
     * Formate une valeur en mm pour l'affichage (avec virgule).
     * @param {number} value - Valeur en mm
     * @returns {string} Valeur formatée avec virgule comme séparateur décimal
     * @example
     * formatMmValue(10.5); // → "10,5"
     */
    function formatMmValue(value) {
        return String(value).replace('.', ',');
    }

    /**
     * Parse une valeur mm depuis un input (avec virgule ou point).
     * @param {string} value - Valeur depuis l'input
     * @returns {number} Valeur numérique en mm
     * @example
     * parseMmValue("10,5"); // → 10.5
     */
    function parseMmValue(value) {
        return parseFloat(String(value).replace(',', '.')) || 0;
    }

    /**
     * Définit l'état d'une checkbox dans une toolbar spécifique.
     * Met à jour l'input ET le wrapper visuel.
     * @param {HTMLElement} toolbar - La toolbar contenant la checkbox
     * @param {string} inputId - L'ID de l'input checkbox
     * @param {boolean} checked - État coché ou non
     * @returns {void}
     */
    function setCheckboxInToolbar(toolbar, inputId, checked) {
        const input = toolbar.querySelector(`#${inputId}`);
        const wrapper = toolbar.querySelector(`#${inputId}-wrapper`);
        if (input) {
            input.checked = checked;
        }
        if (wrapper) {
            wrapper.classList.toggle('checked', checked);
        }
    }

    /**
     * Définit la valeur d'un input dans une toolbar spécifique.
     * @param {HTMLElement} toolbar - La toolbar contenant l'input
     * @param {string} inputId - L'ID de l'input
     * @param {string} value - La valeur à définir
     * @returns {void}
     */
    function setInputInToolbar(toolbar, inputId, value) {
        const input = toolbar.querySelector(`#${inputId}`);
        if (input) {
            input.value = value;
        }
    }

    /**
     * Récupère l'état d'une checkbox dans une toolbar.
     * @param {HTMLElement} toolbar - La toolbar contenant la checkbox
     * @param {string} inputId - L'ID de l'input
     * @returns {boolean} État coché
     */
    function getCheckboxInToolbar(toolbar, inputId) {
        const input = toolbar.querySelector(`#${inputId}`);
        return input ? input.checked : false;
    }

    /**
     * Récupère la valeur d'un input dans une toolbar.
     * @param {HTMLElement} toolbar - La toolbar contenant l'input
     * @param {string} inputId - L'ID de l'input
     * @returns {string} Valeur de l'input
     */
    function getInputInToolbar(toolbar, inputId) {
        const input = toolbar.querySelector(`#${inputId}`);
        return input ? input.value : '';
    }

    /**
     * Réinitialise les contraintes d'une zone aux valeurs par défaut.
     * @param {Object} zoneData - Données de la zone
     * @param {string} scope - Portée du reset : 'all' | 'geometrie'
     * @returns {void}
     */
    function resetConstraintsToDefault(zoneData, scope) {
        if (!zoneData.contrainte) {
            zoneData.contrainte = {};
        }
        
        if (scope === 'all' || scope === 'geometrie') {
            // Reset Géométrie
            zoneData.contrainte.geometrie = {
                positionFixe: false,
                locked: false
                // area, minWMm, minHMm, maxWMm, maxHMm sont supprimés (pas de valeur par défaut)
            };
        }
        
        if (scope === 'all') {
            // Reset Global (sauf selectionnable qui vient d'être modifié)
            if (!zoneData.contrainte.global) {
                zoneData.contrainte.global = {};
            }
            zoneData.contrainte.global.nonSupprimable = false;
            zoneData.contrainte.global.pageModifiable = true;
            zoneData.contrainte.global.imprimable = true;
            // selectionnable est géré séparément
            
            // Reset Style
            zoneData.contrainte.style = {
                contenuModifiable: true,
                typographieModifiable: true,
                alignementsModifiable: true,
                fondModifiable: true,
                bordureModifiable: true,
                affichageModifiable: true,
                apparenceModifiable: true,
                couleursModifiable: true
            };
        }
        
    }

    /**
     * Vérifie si des contraintes de géométrie sont définies (autres que locked).
     * @param {Object} geometrie - Objet contrainte.geometrie
     * @returns {boolean} true si des contraintes sont définies
     */
    function hasGeometryConstraintsDefined(geometrie) {
        if (!geometrie) return false;
        return !!(
            geometrie.positionFixe ||
            geometrie.area ||
            geometrie.minWMm ||
            geometrie.minHMm ||
            geometrie.maxWMm ||
            geometrie.maxHMm
        );
    }

    /**
     * Met à jour la visibilité des sections de contraintes selon l'état des checkboxes maîtres.
     * @param {HTMLElement} toolbar - La toolbar contenant les sections
     * @param {boolean} isSelectionnable - État de la checkbox "Zone sélectionnable"
     * @param {boolean} isLocked - État de la checkbox "Verrouillé"
     * @returns {void}
     */
    function updateConstraintSectionsVisibility(toolbar, isSelectionnable, isLocked) {
        // Éléments à masquer si non sélectionnable
        const globalDetails = toolbar.querySelector('#contrainte-global-details');
        const geometrieSection = toolbar.querySelector('[data-section-id="contrainte-geometrie"]');
        const bornesSection = toolbar.querySelector('#contrainte-bornes-section');
        const styleSection = toolbar.querySelector('#contrainte-style-section');
        
        // Éléments à masquer si verrouillé
        const geometrieDetails = toolbar.querySelector('#contrainte-geometrie-details');
        
        if (!isSelectionnable) {
            // Zone non sélectionnable → tout masquer sauf "Zone sélectionnable"
            if (globalDetails) globalDetails.style.display = 'none';
            if (geometrieSection) geometrieSection.style.display = 'none';
            if (bornesSection) bornesSection.style.display = 'none';
            if (styleSection) styleSection.style.display = 'none';
        } else {
            // Zone sélectionnable → afficher tout
            if (globalDetails) globalDetails.style.display = '';
            if (geometrieSection) geometrieSection.style.display = '';
            if (bornesSection) bornesSection.style.display = '';
            if (styleSection) styleSection.style.display = '';
            
            // Mais si verrouillé → masquer détails géométrie et bornes
            if (isLocked) {
                if (geometrieDetails) geometrieDetails.style.display = 'none';
                if (bornesSection) bornesSection.style.display = 'none';
            } else {
                if (geometrieDetails) geometrieDetails.style.display = '';
                // bornesSection déjà affiché ci-dessus
            }
        }
    }

    /**
     * Charge les contraintes d'une zone dans l'onglet Contraintes de sa toolbar.
     * Remplit les checkboxes et inputs avec les valeurs de zoneData.contrainte.
     * @param {string} zoneId - ID de la zone
     * @param {Object} zoneData - Données de la zone avec ses contraintes
     * @returns {void}
     */
    function loadConstraintsToUI(zoneId, zoneData) {
        const toolbar = getActiveToolbarForType(zoneData.type);
        if (!toolbar) return;
        
        const contrainte = zoneData.contrainte || {};
        const geometrie = contrainte.geometrie || {};
        const global = contrainte.global || {};
        
        // === SECTION GLOBAL ===
        setCheckboxInToolbar(toolbar, 'contrainte-non-supprimable', global.nonSupprimable || false);
        setCheckboxInToolbar(toolbar, 'contrainte-page-modifiable', global.pageModifiable !== false); // défaut true
        // Zone imprimable (défaut: true)
        setCheckboxInToolbar(toolbar, 'contrainte-imprimable', global.imprimable !== false);
        // Zone sélectionnable (défaut: true)
        setCheckboxInToolbar(toolbar, 'contrainte-selectionnable', global.selectionnable !== false);
        
        // === SECTION GÉOMÉTRIE ===
        setCheckboxInToolbar(toolbar, 'contrainte-position-fixe', geometrie.positionFixe || false);
        setCheckboxInToolbar(toolbar, 'contrainte-locked', geometrie.locked || false);
        
        const hasArea = !!(geometrie.area);
        setCheckboxInToolbar(toolbar, 'contrainte-area-active', hasArea);
        
        // Afficher/masquer et remplir les champs area
        const areaFields = toolbar.querySelector('#contrainte-area-fields');
        if (areaFields) {
            areaFields.style.display = hasArea ? '' : 'none';
            if (hasArea && geometrie.area) {
                setInputInToolbar(toolbar, 'contrainte-area-x', formatMmValue(geometrie.area.xMm || 0));
                setInputInToolbar(toolbar, 'contrainte-area-y', formatMmValue(geometrie.area.yMm || 0));
                setInputInToolbar(toolbar, 'contrainte-area-w', formatMmValue(geometrie.area.wMm || 100));
                setInputInToolbar(toolbar, 'contrainte-area-h', formatMmValue(geometrie.area.hMm || 100));
            }
        }
        
        // === SECTION BORNES DE TAILLE ===
        const hasMinSize = !!(geometrie.minWMm || geometrie.minHMm);
        const hasMaxSize = !!(geometrie.maxWMm || geometrie.maxHMm);
        
        setCheckboxInToolbar(toolbar, 'contrainte-taille-min-active', hasMinSize);
        setCheckboxInToolbar(toolbar, 'contrainte-taille-max-active', hasMaxSize);
        
        // Afficher/masquer et remplir les champs taille min
        const minFields = toolbar.querySelector('#contrainte-taille-min-fields');
        if (minFields) {
            minFields.style.display = hasMinSize ? '' : 'none';
            if (hasMinSize) {
                setInputInToolbar(toolbar, 'contrainte-min-w', formatMmValue(geometrie.minWMm || 0));
                setInputInToolbar(toolbar, 'contrainte-min-h', formatMmValue(geometrie.minHMm || 0));
            }
        }
        // Afficher/masquer le bouton Mémoriser taille min
        const btnMemoMin = toolbar.querySelector('#btn-memoriser-taille-min');
        const lblMemoMin = btnMemoMin?.closest('.form-row-poc')?.querySelector('.memoriser-label');
        if (btnMemoMin) btnMemoMin.style.display = hasMinSize ? '' : 'none';
        if (lblMemoMin) lblMemoMin.style.display = hasMinSize ? '' : 'none';
        
        // Afficher/masquer et remplir les champs taille max
        const maxFields = toolbar.querySelector('#contrainte-taille-max-fields');
        if (maxFields) {
            maxFields.style.display = hasMaxSize ? '' : 'none';
            if (hasMaxSize) {
                setInputInToolbar(toolbar, 'contrainte-max-w', formatMmValue(geometrie.maxWMm || 0));
                setInputInToolbar(toolbar, 'contrainte-max-h', formatMmValue(geometrie.maxHMm || 0));
            }
        }
        // Afficher/masquer le bouton Mémoriser taille max
        const btnMemoMax = toolbar.querySelector('#btn-memoriser-taille-max');
        const lblMemoMax = btnMemoMax?.closest('.form-row-poc')?.querySelector('.memoriser-label');
        if (btnMemoMax) btnMemoMax.style.display = hasMaxSize ? '' : 'none';
        if (lblMemoMax) lblMemoMax.style.display = hasMaxSize ? '' : 'none';
        
        // === SECTION STYLE (Sections modifiables) ===
        const style = contrainte.style || {};
        const zoneType = zoneData.type;
        
        // Checkboxes communes ou spécifiques selon le type de zone
        // Zone Texte (textQuill/text) : contenu, typographie, alignements, fond, bordure
        // Zone Image : contenu, affichage, fond, bordure
        // Zone Barcode : contenu, apparence, fond
        // Zone QR : couleurs
        
        // Contenu (texte uniquement) - utilise contenuModifiable
        if (zoneType === 'textQuill' || zoneType === 'text') {
            setCheckboxInToolbar(toolbar, 'contrainte-contenu', style.contenuModifiable !== false);
        }
        
        // Barcode : typeCodeModifiable + typeSourceModifiable + donneesModifiable (granularité spécifique)
        if (zoneType === 'barcode') {
            setCheckboxInToolbar(toolbar, 'contrainte-type-code', style.typeCodeModifiable !== false);
            setCheckboxInToolbar(toolbar, 'contrainte-type-source', style.typeSourceModifiable !== false);
            // Rétrocompat : si donneesModifiable absent mais contenuModifiable présent, utiliser contenuModifiable
            const donneesModif = style.donneesModifiable !== undefined ? style.donneesModifiable : style.contenuModifiable;
            setCheckboxInToolbar(toolbar, 'contrainte-contenu', donneesModif !== false);
        }
        
        // Image : typeSourceModifiable + imageModifiable (granularité spécifique)
        if (zoneType === 'image') {
            setCheckboxInToolbar(toolbar, 'contrainte-type-source', style.typeSourceModifiable !== false);
            // Rétrocompat : si imageModifiable absent mais contenuModifiable présent, utiliser contenuModifiable
            const imageModif = style.imageModifiable !== undefined ? style.imageModifiable : style.contenuModifiable;
            setCheckboxInToolbar(toolbar, 'contrainte-contenu', imageModif !== false);
        }
        
        // Typographie (texte uniquement)
        if (zoneType === 'textQuill' || zoneType === 'text') {
            setCheckboxInToolbar(toolbar, 'contrainte-typographie', style.typographieModifiable !== false);
            setCheckboxInToolbar(toolbar, 'contrainte-alignements', style.alignementsModifiable !== false);
        }
        
        // Affichage (image uniquement)
        if (zoneType === 'image') {
            setCheckboxInToolbar(toolbar, 'contrainte-affichage', style.affichageModifiable !== false);
        }
        
        // Apparence (barcode uniquement)
        if (zoneType === 'barcode') {
            setCheckboxInToolbar(toolbar, 'contrainte-apparence', style.apparenceModifiable !== false);
        }
        
        // Couleurs (QR uniquement)
        if (zoneType === 'qr') {
            setCheckboxInToolbar(toolbar, 'contrainte-couleurs', style.couleursModifiable !== false);
        }
        
        // Fond (texte, image, barcode)
        if (zoneType === 'textQuill' || zoneType === 'text' || zoneType === 'image' || zoneType === 'barcode') {
            setCheckboxInToolbar(toolbar, 'contrainte-fond', style.fondModifiable !== false);
        }
        
        // Bordure (texte, image)
        if (zoneType === 'textQuill' || zoneType === 'text' || zoneType === 'image') {
            setCheckboxInToolbar(toolbar, 'contrainte-bordure', style.bordureModifiable !== false);
        }
        
        
        // Mettre à jour la visibilité des sections selon l'état des checkboxes maîtres
        const isSelectionnable = getCheckboxInToolbar(toolbar, 'contrainte-selectionnable');
        const isLocked = getCheckboxInToolbar(toolbar, 'contrainte-locked');
        updateConstraintSectionsVisibility(toolbar, isSelectionnable, isLocked);
        
    }

    /**
     * Sauvegarde les contraintes depuis l'UI vers la zone sélectionnée.
     * Lit les valeurs des checkboxes et inputs et les stocke dans zoneData.contrainte.
     * @param {string} zoneId - ID de la zone
     * @param {Object} zoneData - Données de la zone
     * @param {HTMLElement} toolbar - La toolbar contenant les contrôles
     * @returns {void}
     */
    function saveConstraintsFromUI(zoneId, zoneData, toolbar) {
        if (!toolbar) return;
        
        // Initialiser la structure contrainte si nécessaire
        if (!zoneData.contrainte) {
            zoneData.contrainte = {};
        }
        if (!zoneData.contrainte.geometrie) {
            zoneData.contrainte.geometrie = {};
        }
        if (!zoneData.contrainte.global) {
            zoneData.contrainte.global = {};
        }
        
        const geometrie = zoneData.contrainte.geometrie;
        const global = zoneData.contrainte.global;
        
        // === SECTION GLOBAL ===
        global.nonSupprimable = getCheckboxInToolbar(toolbar, 'contrainte-non-supprimable');
        global.pageModifiable = getCheckboxInToolbar(toolbar, 'contrainte-page-modifiable');
        global.imprimable = getCheckboxInToolbar(toolbar, 'contrainte-imprimable');
        global.selectionnable = getCheckboxInToolbar(toolbar, 'contrainte-selectionnable');
        
        // === SECTION GÉOMÉTRIE ===
        geometrie.positionFixe = getCheckboxInToolbar(toolbar, 'contrainte-position-fixe');
        geometrie.locked = getCheckboxInToolbar(toolbar, 'contrainte-locked');
        
        // Area
        const areaActive = getCheckboxInToolbar(toolbar, 'contrainte-area-active');
        if (areaActive) {
            geometrie.area = {
                xMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-x')),
                yMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-y')),
                wMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-w')),
                hMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-h'))
            };
        } else {
            delete geometrie.area;
        }
        
        // Bornes de taille
        const minActive = getCheckboxInToolbar(toolbar, 'contrainte-taille-min-active');
        if (minActive) {
            geometrie.minWMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-min-w'));
            geometrie.minHMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-min-h'));
        } else {
            delete geometrie.minWMm;
            delete geometrie.minHMm;
        }
        
        const maxActive = getCheckboxInToolbar(toolbar, 'contrainte-taille-max-active');
        if (maxActive) {
            geometrie.maxWMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-max-w'));
            geometrie.maxHMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-max-h'));
        } else {
            delete geometrie.maxWMm;
            delete geometrie.maxHMm;
        }
        
        // === SECTION STYLE (Sections modifiables) ===
        // Initialiser la structure style si nécessaire
        if (!zoneData.contrainte.style) {
            zoneData.contrainte.style = {};
        }
        const style = zoneData.contrainte.style;
        const zoneType = zoneData.type;
        
        // Sauvegarder uniquement les checkboxes présentes pour ce type de zone
        // Zone Texte (textQuill/text) : contenu, typographie, alignements, fond, bordure
        // Zone Image : contenu, affichage, fond, bordure
        // Zone Barcode : contenu, apparence, fond
        // Zone QR : couleurs
        
        // Contenu (texte uniquement) - utilise contenuModifiable
        if (zoneType === 'textQuill' || zoneType === 'text') {
            style.contenuModifiable = getCheckboxInToolbar(toolbar, 'contrainte-contenu');
        }
        
        // Barcode : typeCodeModifiable + typeSourceModifiable + donneesModifiable (granularité spécifique)
        if (zoneType === 'barcode') {
            style.typeCodeModifiable = getCheckboxInToolbar(toolbar, 'contrainte-type-code');
            style.typeSourceModifiable = getCheckboxInToolbar(toolbar, 'contrainte-type-source');
            style.donneesModifiable = getCheckboxInToolbar(toolbar, 'contrainte-contenu');
            // Supprimer l'ancienne propriété si présente (migration)
            delete style.contenuModifiable;
        }
        
        // Image : typeSourceModifiable + imageModifiable (granularité spécifique)
        if (zoneType === 'image') {
            style.typeSourceModifiable = getCheckboxInToolbar(toolbar, 'contrainte-type-source');
            style.imageModifiable = getCheckboxInToolbar(toolbar, 'contrainte-contenu');
            // Supprimer l'ancienne propriété si présente (migration)
            delete style.contenuModifiable;
        }
        
        // Typographie et alignements (texte uniquement)
        if (zoneType === 'textQuill' || zoneType === 'text') {
            style.typographieModifiable = getCheckboxInToolbar(toolbar, 'contrainte-typographie');
            style.alignementsModifiable = getCheckboxInToolbar(toolbar, 'contrainte-alignements');
        }
        
        // Affichage (image uniquement)
        if (zoneType === 'image') {
            style.affichageModifiable = getCheckboxInToolbar(toolbar, 'contrainte-affichage');
        }
        
        // Apparence (barcode uniquement)
        if (zoneType === 'barcode') {
            style.apparenceModifiable = getCheckboxInToolbar(toolbar, 'contrainte-apparence');
        }
        
        // Couleurs (QR uniquement)
        if (zoneType === 'qr') {
            style.couleursModifiable = getCheckboxInToolbar(toolbar, 'contrainte-couleurs');
        }
        
        // Fond (texte, image, barcode)
        if (zoneType === 'textQuill' || zoneType === 'text' || zoneType === 'image' || zoneType === 'barcode') {
            style.fondModifiable = getCheckboxInToolbar(toolbar, 'contrainte-fond');
        }
        
        // Bordure (texte, image)
        if (zoneType === 'textQuill' || zoneType === 'text' || zoneType === 'image') {
            style.bordureModifiable = getCheckboxInToolbar(toolbar, 'contrainte-bordure');
        }
        
    }

    /**
     * Sauvegarde les contraintes de la zone actuellement sélectionnée.
     * Appelée lors de la modification d'un contrôle dans l'onglet Contraintes.
     * @param {HTMLElement} toolbar - La toolbar contenant les contrôles de contraintes
     * @returns {void}
     */
    function saveCurrentZoneConstraints(toolbar) {
        if (!toolbar) return;
        if (typeof selectedZoneIds === 'undefined' || selectedZoneIds.length !== 1) return;
        
        const zoneId = selectedZoneIds[0];
        const zones = getCurrentPageZones();
        const zoneData = zones[zoneId];
        if (!zoneData) return;
        
        saveConstraintsFromUI(zoneId, zoneData, toolbar);
        
        // Mettre à jour la visibilité de la section Alignement page
        // car les contraintes modifiées peuvent affecter sa visibilité
        updateSidebarSectionsVisibility();
    }

    /**
     * Applique les contraintes géométriques de la zone sélectionnée en temps réel.
     * Appelé uniquement en mode Template lors de modifications.
     * @returns {void}
     */
    function applyCurrentZoneGeometryConstraints() {
        if (typeof selectedZoneIds === 'undefined' || selectedZoneIds.length !== 1) return;
        
        const zoneId = selectedZoneIds[0];
        const zones = getCurrentPageZones();
        const zoneData = zones[zoneId];
        if (!zoneData || !zoneData.contrainte) return;
        
        const geometrie = zoneData.contrainte.geometrie;
        if (!geometrie) return;
        
        // Mettre à jour la visualisation de l'area si elle existe
        if (geometrie.area) {
            updateAreaVisualization(zoneId, geometrie.area);
        } else {
            removeAreaVisualization(zoneId);
        }
        
        // Note: Le blocage du drag/resize est géré par les fonctions existantes
        // qui vérifient déjà les contraintes lors des interactions
        
    }

    /**
     * Met à jour la visualisation de la zone area (rectangle de contrainte).
     * @param {string} zoneId - ID de la zone
     * @param {Object} area - Objet area avec xMm, yMm, wMm, hMm
     * @returns {void}
     */
    function updateAreaVisualization(zoneId, area) {
        // Utiliser la fonction existante createAreaElement
        // Elle supprime l'ancienne area avant d'en créer une nouvelle
        createAreaElement(zoneId, area);
        
        // Afficher l'area si la zone est sélectionnée
        if (selectedZoneIds.length === 1 && selectedZoneIds[0] === zoneId) {
            updateAreaVisibility(zoneId, true);
        }
    }

    /**
     * Supprime la visualisation de la zone area.
     * @param {string} zoneId - ID de la zone
     * @returns {void}
     */
    function removeAreaVisualization(zoneId) {
        // Utiliser la fonction existante removeAreaElement
        removeAreaElement(zoneId);
    }

    /**
     * Gère le clic sur une checkbox de contrainte.
     * Toggle l'état et met à jour les champs conditionnels.
     * @param {HTMLElement} wrapper - Le wrapper de la checkbox
     * @returns {void}
     */
    function handleConstraintCheckboxClick(wrapper) {
        const input = wrapper.querySelector('input[type="checkbox"]');
        if (!input) return;
        
        const inputId = input.id;
        const toolbar = wrapper.closest('.toolbar-poc');
        const newCheckedState = !input.checked;
        
        // Récupérer les données de la zone sélectionnée
        const zoneId = selectedZoneIds.length === 1 ? selectedZoneIds[0] : null;
        const zones = getCurrentPageZones();
        const zoneData = zoneId ? zones[zoneId] : null;
        
        // === CAS SPÉCIAL : Zone sélectionnable ===
        if (inputId === 'contrainte-selectionnable' && !newCheckedState && zoneData) {
            // On décoche "Zone sélectionnable" → reset toutes les contraintes
            resetConstraintsToDefault(zoneData, 'all');
            // Mettre selectionnable à false dans les données
            if (zoneData.contrainte && zoneData.contrainte.global) {
                zoneData.contrainte.global.selectionnable = false;
            }
            removeAreaVisualization(zoneId);
        }
        
        // === CAS SPÉCIAL : Verrouillé ===
        if (inputId === 'contrainte-locked' && newCheckedState && zoneData) {
            // On coche "Verrouillé" → reset contraintes géométrie
            resetConstraintsToDefault(zoneData, 'geometrie');
            // Mettre locked à true dans les données
            if (zoneData.contrainte && zoneData.contrainte.geometrie) {
                zoneData.contrainte.geometrie.locked = true;
            }
            removeAreaVisualization(zoneId);
        }
        
        // Toggle l'état de la checkbox
        input.checked = newCheckedState;
        wrapper.classList.toggle('checked', newCheckedState);
        
        // Déterminer si on a fait un reset
        const didResetAll = (inputId === 'contrainte-selectionnable' && !newCheckedState && zoneData);
        const didResetGeometrie = (inputId === 'contrainte-locked' && newCheckedState && zoneData);
        
        // Si on a fait un reset, recharger l'UI pour refléter les valeurs par défaut
        // et NE PAS sauvegarder (les données sont déjà correctes via resetConstraintsToDefault)
        if (didResetAll || didResetGeometrie) {
            // Recharger l'UI avec les valeurs reset
            loadConstraintsToUI(zoneId, zoneData);
            
            // Mettre à jour la visibilité des sections
            const isSelectionnable = getCheckboxInToolbar(toolbar, 'contrainte-selectionnable');
            const isLocked = getCheckboxInToolbar(toolbar, 'contrainte-locked');
            updateConstraintSectionsVisibility(toolbar, isSelectionnable, isLocked);
            
            // Appliquer les contraintes géométriques (pour supprimer l'area visuellement)
            if (isTemplateMode()) {
                applyCurrentZoneGeometryConstraints();
            }
            
            // Mettre à jour la section Alignement page dans la sidebar
            updateSidebarSectionsVisibility();
            
            return; // Sortir ici, pas besoin de sauvegarder
        }
        
        // Afficher/masquer les champs conditionnels existants
        if (inputId === 'contrainte-area-active') {
            const areaFields = toolbar.querySelector('#contrainte-area-fields');
            const zoneIdForArea = selectedZoneIds.length === 1 ? selectedZoneIds[0] : null;
            
            if (areaFields) {
                areaFields.style.display = newCheckedState ? '' : 'none';
            }
            
            if (newCheckedState && zoneIdForArea) {
                // On coche : initialiser et afficher l'area
                const zoneEl = document.getElementById(zoneIdForArea);
                const zonesDataForArea = getCurrentPageZones();
                const zoneDataForArea = zonesDataForArea[zoneIdForArea];
                
                // Vérifier si l'area n'était pas déjà définie (premier cochage)
                const wasAreaDefined = zoneDataForArea?.contrainte?.geometrie?.area;
                
                let areaToDisplay = null;
                
                if (!wasAreaDefined && zoneEl) {
                    // Premier cochage : DOM px → format fini mm pour calcul area initiale
                    const fpAreaInit = getFondPerduOffset();
                    const zoneXMm = pxToMm(zoneEl.offsetLeft - fpAreaInit.gauchePx);
                    const zoneYMm = pxToMm(zoneEl.offsetTop - fpAreaInit.hautPx);
                    const zoneWMm = pxToMm(zoneEl.offsetWidth);
                    const zoneHMm = pxToMm(zoneEl.offsetHeight);
                    
                    // Calculer les valeurs initiales centrées et contraintes
                    areaToDisplay = calculateInitialAreaValues(zoneXMm, zoneYMm, zoneWMm, zoneHMm);
                    
                    // Remplir les champs
                    setInputInToolbar(toolbar, 'contrainte-area-x', formatMmValue(areaToDisplay.xMm));
                    setInputInToolbar(toolbar, 'contrainte-area-y', formatMmValue(areaToDisplay.yMm));
                    setInputInToolbar(toolbar, 'contrainte-area-w', formatMmValue(areaToDisplay.wMm));
                    setInputInToolbar(toolbar, 'contrainte-area-h', formatMmValue(areaToDisplay.hMm));
                    
                } else if (wasAreaDefined) {
                    // L'area existait déjà : utiliser les valeurs existantes
                    areaToDisplay = wasAreaDefined;
                }
                
                // Créer et afficher l'area immédiatement
                if (areaToDisplay) {
                    createAreaElement(zoneIdForArea, areaToDisplay);
                    updateAreaVisibility(zoneIdForArea, true);
                }
            } else if (!newCheckedState && zoneIdForArea) {
                // On décoche : supprimer l'area visuellement
                removeAreaElement(zoneIdForArea);
            }
        }
        
        if (inputId === 'contrainte-taille-min-active') {
            const minFields = toolbar.querySelector('#contrainte-taille-min-fields');
            if (minFields) {
                minFields.style.display = newCheckedState ? '' : 'none';
            }
            // Afficher/masquer le bouton Mémoriser
            const btnMemoMin = wrapper.closest('.form-row-poc')?.querySelector('.btn-memoriser');
            const lblMemoMin = wrapper.closest('.form-row-poc')?.querySelector('.memoriser-label');
            if (btnMemoMin) btnMemoMin.style.display = newCheckedState ? '' : 'none';
            if (lblMemoMin) lblMemoMin.style.display = newCheckedState ? '' : 'none';
        }
        
        if (inputId === 'contrainte-taille-max-active') {
            const maxFields = toolbar.querySelector('#contrainte-taille-max-fields');
            if (maxFields) {
                maxFields.style.display = newCheckedState ? '' : 'none';
            }
            // Afficher/masquer le bouton Mémoriser
            const btnMemoMax = wrapper.closest('.form-row-poc')?.querySelector('.btn-memoriser');
            const lblMemoMax = wrapper.closest('.form-row-poc')?.querySelector('.memoriser-label');
            if (btnMemoMax) btnMemoMax.style.display = newCheckedState ? '' : 'none';
            if (lblMemoMax) lblMemoMax.style.display = newCheckedState ? '' : 'none';
        }
        
        // Mettre à jour la visibilité des sections
        const isSelectionnable = getCheckboxInToolbar(toolbar, 'contrainte-selectionnable');
        const isLocked = getCheckboxInToolbar(toolbar, 'contrainte-locked');
        updateConstraintSectionsVisibility(toolbar, isSelectionnable, isLocked);
        
        // Sauvegarder les contraintes (seulement si pas de reset)
        saveCurrentZoneConstraints(toolbar);
        
        // Appliquer les contraintes géométriques en temps réel (mode Template)
        if (isTemplateMode()) {
            applyCurrentZoneGeometryConstraints();
        }
    }

    /**
     * Gère la modification d'un input de contrainte.
     * Valide et contraint les valeurs aux limites du document.
     * @param {HTMLElement} input - L'input modifié
     * @returns {void}
     */
    function handleConstraintInputChange(input) {
        const toolbar = input.closest('.toolbar-poc');
        const inputId = input.id;
        
        // Valider les champs géométriques (area et tailles)
        const geometryFields = {
            'contrainte-area-x': 'areaX',
            'contrainte-area-y': 'areaY',
            'contrainte-area-w': 'areaW',
            'contrainte-area-h': 'areaH',
            'contrainte-min-w': 'minW',
            'contrainte-min-h': 'minH',
            'contrainte-max-w': 'maxW',
            'contrainte-max-h': 'maxH'
        };
        
        if (geometryFields[inputId]) {
            const fieldType = geometryFields[inputId];
            const rawValue = parseMmValue(input.value);
            
            // Contexte pour la validation
            let validationContext = null;
            
            // Pour les champs area, récupérer le contexte de l'area
            if (fieldType.startsWith('area')) {
                validationContext = {
                    xMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-x')),
                    yMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-y')),
                    wMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-w')),
                    hMm: parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-h'))
                };
            }
            
            // Pour les champs min/max, récupérer la position de la zone ET l'area si active
            if (fieldType.startsWith('min') || fieldType.startsWith('max')) {
                const zoneId = selectedZoneIds.length === 1 ? selectedZoneIds[0] : null;
                if (zoneId) {
                    const zoneEl = document.getElementById(zoneId);
                    const zones = getCurrentPageZones();
                    const zoneData = zones[zoneId];
                    
                    if (zoneEl) {
                        const fpValCtx = getFondPerduOffset();
                        validationContext = {
                            zoneXMm: pxToMm(zoneEl.offsetLeft - fpValCtx.gauchePx),
                            zoneYMm: pxToMm(zoneEl.offsetTop - fpValCtx.hautPx)
                        };
                        
                        // Ajouter les limites de l'area si active
                        const areaActive = getCheckboxInToolbar(toolbar, 'contrainte-area-active');
                        if (areaActive && zoneData?.contrainte?.geometrie?.area) {
                            const area = zoneData.contrainte.geometrie.area;
                            validationContext.areaXMm = area.xMm;
                            validationContext.areaYMm = area.yMm;
                            validationContext.areaWMm = area.wMm;
                            validationContext.areaHMm = area.hMm;
                        }
                    }
                }
            }
            
            // Valider et corriger si nécessaire
            const validatedValue = validateConstraintValue(rawValue, fieldType, validationContext);
            
            // Si la valeur a été corrigée, mettre à jour l'input
            if (Math.abs(validatedValue - rawValue) > 0.01) {
                input.value = formatMmValue(validatedValue);
            }
        }
        
        // Si c'est un champ area, mettre à jour l'area visuellement
        if (['contrainte-area-x', 'contrainte-area-y', 'contrainte-area-w', 'contrainte-area-h'].includes(inputId)) {
            const zoneId = selectedZoneIds.length === 1 ? selectedZoneIds[0] : null;
            if (zoneId) {
                const areaEl = areaElements.get(zoneId);
                const zoneEl = document.getElementById(zoneId);
                if (areaEl) {
                    // Récupérer l'ancienne position de l'area avant modification
                    const oldAreaX = areaEl.offsetLeft;
                    const oldAreaY = areaEl.offsetTop;
                    
                    // Nouvelles valeurs de l'area
                    const xMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-x'));
                    const yMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-y'));
                    const wMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-w'));
                    const hMm = parseMmValue(getInputInToolbar(toolbar, 'contrainte-area-h'));
                    
                    const fpAreaInput = getFondPerduOffset();
                    const newAreaX = mmToPx(xMm) + fpAreaInput.gauchePx;
                    const newAreaY = mmToPx(yMm) + fpAreaInput.hautPx;
                    const newAreaW = mmToPx(wMm);
                    const newAreaH = mmToPx(hMm);
                    
                    // Appliquer les nouvelles dimensions à l'area (page DOM px)
                    areaEl.style.left = newAreaX + 'px';
                    areaEl.style.top = newAreaY + 'px';
                    areaEl.style.width = newAreaW + 'px';
                    areaEl.style.height = newAreaH + 'px';
                    
                    // Déplacer la zone avec l'area (même delta)
                    if (zoneEl && (inputId === 'contrainte-area-x' || inputId === 'contrainte-area-y')) {
                        const deltaX = newAreaX - oldAreaX;
                        const deltaY = newAreaY - oldAreaY;
                        
                        let newZoneX = zoneEl.offsetLeft + deltaX;
                        let newZoneY = zoneEl.offsetTop + deltaY;
                        
                        // Contraindre la zone pour rester dans l'area
                        newZoneX = Math.max(newAreaX, Math.min(newZoneX, newAreaX + newAreaW - zoneEl.offsetWidth));
                        newZoneY = Math.max(newAreaY, Math.min(newZoneY, newAreaY + newAreaH - zoneEl.offsetHeight));
                        
                        // Appliquer la nouvelle position à la zone
                        zoneEl.style.left = newZoneX + 'px';
                        zoneEl.style.top = newZoneY + 'px';
                        
                        // Mettre à jour les données de la zone
                        const zones = getCurrentPageZones();
                        const zoneData = zones[zoneId];
                        if (zoneData) {
                            zoneData.x = pxToMm(newZoneX);
                            zoneData.y = pxToMm(newZoneY);
                        }
                        
                    }
                }
            }
        }
        
        // Sauvegarder les contraintes EN PASSANT LA TOOLBAR
        saveCurrentZoneConstraints(toolbar);
        
        // Appliquer les contraintes géométriques en temps réel (mode Template)
        if (isTemplateMode()) {
            applyCurrentZoneGeometryConstraints();
        }
    }

    /**
     * Initialise les event listeners pour l'onglet Contraintes.
     * Utilise la délégation d'événements pour gérer tous les contrôles.
     * @returns {void}
     */
    function initConstraintsTabListeners() {
        // Gestion des checkboxes de contraintes (wrappers) - phase capture
        document.addEventListener('click', function(e) {
            const wrapper = e.target.closest('[id^="contrainte-"][id$="-wrapper"]');
            if (wrapper && wrapper.closest('[data-tab-content="contraintes"]')) {
                handleConstraintCheckboxClick(wrapper);
                return;
            }
        }, true);
        
        // Gestion des inputs texte de contraintes - validation sur 'change' (blur ou Entrée)
        // Utiliser 'change' au lieu de 'input' pour permettre à l'utilisateur de finir sa saisie
        document.addEventListener('change', function(e) {
            const input = e.target.closest('[data-tab-content="contraintes"] input[type="text"]');
            if (input) {
                handleConstraintInputChange(input);
                return;
            }
        });
        
        // Gestion des boutons "Mémoriser" - useCapture=true car les toolbars font stopPropagation()
        document.addEventListener('click', function(e) {
            const btn = e.target.closest('.btn-memoriser');
            if (!btn) return;
            
            const btnId = btn.id;
            const toolbar = btn.closest('.toolbar-poc');
            if (!toolbar) return;
            
            // Récupérer la zone sélectionnée
            const zoneIdForMemo = selectedZoneIds.length === 1 ? selectedZoneIds[0] : null;
            if (!zoneIdForMemo) {
                showConstraintToast('Aucune zone sélectionnée', 'warning');
                return;
            }
            
            const zoneEl = document.getElementById(zoneIdForMemo);
            if (!zoneEl) return;
            
            // Récupérer les dimensions actuelles de la zone en mm
            const widthMm = pxToMm(zoneEl.offsetWidth);
            const heightMm = pxToMm(zoneEl.offsetHeight);
            
            // Valider aux limites du document
            const limits = getGeometryLimits();
            const usableWidth = limits.pageWidthMm - (2 * limits.marginMm);
            const usableHeight = limits.pageHeightMm - (2 * limits.marginMm);
            
            const validatedWidth = Math.min(widthMm, usableWidth);
            const validatedHeight = Math.min(heightMm, usableHeight);
            
            if (btnId === 'btn-memoriser-taille-min') {
                setInputInToolbar(toolbar, 'contrainte-min-w', formatMmValue(validatedWidth));
                setInputInToolbar(toolbar, 'contrainte-min-h', formatMmValue(validatedHeight));
                
                // Sauvegarder les contraintes
                saveCurrentZoneConstraints(toolbar);
                
                showConstraintToast(`Taille minimum mémorisée : ${formatMmValue(validatedWidth)} × ${formatMmValue(validatedHeight)} mm`, 'info', 'check_circle');
            }
            
            if (btnId === 'btn-memoriser-taille-max') {
                setInputInToolbar(toolbar, 'contrainte-max-w', formatMmValue(validatedWidth));
                setInputInToolbar(toolbar, 'contrainte-max-h', formatMmValue(validatedHeight));
                
                // Sauvegarder les contraintes
                saveCurrentZoneConstraints(toolbar);
                
                showConstraintToast(`Taille maximum mémorisée : ${formatMmValue(validatedWidth)} × ${formatMmValue(validatedHeight)} mm`, 'info', 'check_circle');
            }
            
            // Appliquer les contraintes en temps réel (mode Template)
            if (isTemplateMode()) {
                applyCurrentZoneGeometryConstraints();
            }
        }, true); // useCapture=true car les toolbars font stopPropagation()
        
        // Gestion du drag/resize des areas (mode Template)
        document.addEventListener('mousedown', function(e) {
            if (!isTemplateMode()) return;
            const areaEl = e.target.closest('.zone-area');
            if (areaEl) {
                startAreaInteraction(e);
            }
        }, true); // useCapture pour intercepter avant les autres handlers
        
        document.addEventListener('mousemove', function(e) {
            if (isAreaDragging || isAreaResizing) {
                handleAreaMove(e);
            }
        });
        
        document.addEventListener('mouseup', function(e) {
            if (isAreaDragging || isAreaResizing) {
                endAreaInteraction(e);
            }
        });
        
    }

